const atlasData: any = {"domains":[{"id":"enterprise","stage":1,"verb":"PLAN","name":"Business & Enterprise","tagline":"Decide, design and work together","cvar":"var(--c-biz)","hex":"#ff8f6b","cats":[{"id":"enterprise-architecture-modeling","name":"Architecture & Modeling","description":"Visual modeling approaches and tools for enterprise and software architecture.","tools":["ArchiMate","UML","C4 Model","Lucidchart","draw.io","Enterprise Architect","Archi","Mermaid","BPMN","Miro"]},{"id":"enterprise-design-ux","name":"Design & UX","description":"Experience design, prototyping, design systems, and visual assets.","tools":["Figma","Sketch","Adobe XD","Storybook","Zeplin","Framer","Canva","InVision","Penpot","Lottie"]},{"id":"enterprise-project-collaboration","name":"Project & Collaboration","description":"Planning, coordination, knowledge sharing, and team collaboration.","tools":["Jira","Confluence","Slack","Microsoft Teams","Trello","Asana","Notion","Monday.com","Miro","SharePoint"]},{"id":"enterprise-enterprise-platforms-itsm","name":"Enterprise Platforms & ITSM","description":"Enterprise systems for business operations, customers, and IT services.","tools":["SAP","Oracle Fusion","Salesforce","Workday","Dynamics 365","ServiceNow","NetSuite","Zendesk","Freshservice","BMC Helix"]},{"id":"enterprise-low-code-rpa-automation","name":"Low-Code, RPA & Automation","description":"Workflow automation, low-code applications, and robotic process automation.","tools":["Power Platform","OutSystems","Mendix","Appian","UiPath","Automation Anywhere","Zapier","n8n","Make","Power Automate"]},{"id":"enterprise-workplace-endpoint","name":"Workplace & Endpoint","description":"Workplace productivity, identity, endpoint, and communications platforms.","tools":["Microsoft 365","Google Workspace","Intune","Jamf","Entra ID","Zoom","Citrix","Workspace ONE","Webex","Google Meet"]}]},{"id":"build","stage":2,"verb":"BUILD","name":"Build","tagline":"Write the product","cvar":"var(--c-build)","hex":"#4f9bff","cats":[{"id":"build-programming-languages","name":"Programming Languages","description":"Languages used to create software and services.","tools":["Python","Java","JavaScript","TypeScript","C#","C++","Go","Rust","Kotlin","Swift","PHP","Ruby","Scala","R"]},{"id":"build-frontend","name":"Frontend","description":"Technologies for building browser-based user interfaces.","tools":["HTML5","CSS3","React","Angular","Vue.js","Svelte","Next.js","Tailwind CSS","Bootstrap","Vite"]},{"id":"build-mobile-cross-platform","name":"Mobile & Cross-Platform","description":"Mobile app platforms and cross-platform development frameworks.","tools":["Android","iOS","Flutter","React Native","SwiftUI","Jetpack Compose",".NET MAUI","Ionic","Kotlin Multiplatform","Expo"]},{"id":"build-backend-frameworks","name":"Backend & Frameworks","description":"Server-side application runtimes, APIs, and web frameworks.","tools":["Node.js","Spring Boot",".NET","Django","FastAPI","Flask","Express.js","NestJS","Laravel","Ruby on Rails"]},{"id":"build-apis-integration","name":"APIs & Integration","description":"Integration patterns, interface definitions, and API management.","tools":["REST","GraphQL","gRPC","OpenAPI","Kong","Apigee","MuleSoft","WSO2","Apache Camel","Boomi"]},{"id":"build-ides-dev-tools","name":"IDEs & Dev Tools","description":"Development environments and supporting build tooling.","tools":["VS Code","IntelliJ IDEA","Visual Studio","Eclipse","PyCharm","Android Studio","Xcode","Maven","Gradle","npm"]}]},{"id":"data","stage":3,"verb":"KNOW","name":"Data & AI","tagline":"Store, move and learn from data","cvar":"var(--c-data)","hex":"#b58cff","cats":[{"id":"data-relational-databases","name":"Relational Databases","description":"Structured data stores designed around relational models.","tools":["MySQL","PostgreSQL","Oracle DB","SQL Server","MariaDB","SQLite","IBM Db2","Amazon Aurora","Azure SQL","Cloud SQL"]},{"id":"data-nosql-search","name":"NoSQL & Search","description":"Non-relational data, graph, time-series, and search technologies.","tools":["MongoDB","Redis","Cassandra","DynamoDB","Elasticsearch","Neo4j","Couchbase","Cosmos DB","InfluxDB","OpenSearch"]},{"id":"data-messaging-streaming","name":"Messaging & Streaming","description":"Services that connect systems through events, queues, and data streams.","tools":["Kafka","RabbitMQ","ActiveMQ","Pulsar","Amazon SQS","Azure Service Bus","Google Pub/Sub","NATS","Flink","Kinesis"]},{"id":"data-data-engineering","name":"Data Engineering","description":"Data pipelines, transformation, processing, and analytical platforms.","tools":["Apache Spark","Hadoop","Airflow","dbt","Databricks","Snowflake","BigQuery","Redshift","Fivetran","Talend"]},{"id":"data-bi-visualization","name":"BI & Visualization","description":"Tools for reporting, dashboards, and business intelligence.","tools":["Power BI","Tableau","Looker","Qlik","Superset","Metabase","Excel","QuickSight","Sisense","Domo"]},{"id":"data-ai-ml-genai","name":"AI, ML & GenAI","description":"Machine learning, generative AI, model operations, and managed AI platforms.","tools":["TensorFlow","PyTorch","scikit-learn","Hugging Face","LangChain","LlamaIndex","MLflow","Kubeflow","OpenAI","Claude","Gemini","Amazon Bedrock","Azure AI Foundry","Vertex AI"]},{"id":"data-ai-agents-vector-stores","name":"AI Agents & Vector Stores","description":"Agent orchestration, tool integration, and vector retrieval technologies.","tools":["Pinecone","Weaviate","Milvus","Chroma","pgvector","Qdrant","MCP","LangGraph","CrewAI","AutoGen"]}]},{"id":"cloud","stage":4,"verb":"RUN","name":"Platform & Cloud","tagline":"Where software lives and scales","cvar":"var(--c-plat)","hex":"#2ee6c9","cats":[{"id":"cloud-cloud-platforms","name":"Cloud Platforms","description":"Infrastructure and application services delivered through cloud providers.","tools":["AWS","Microsoft Azure","Google Cloud","Oracle Cloud","IBM Cloud","Alibaba Cloud","Cloudflare","DigitalOcean","Akamai","Linode"]},{"id":"cloud-containers-orchestration","name":"Containers & Orchestration","description":"Packaging, scheduling, operating, and networking containerized workloads.","tools":["Docker","Kubernetes","OpenShift","Helm","Podman","Rancher","Istio","containerd","Amazon EKS","Azure AKS"]},{"id":"cloud-infrastructure-as-code","name":"Infrastructure as Code","description":"Provisioning and controlling infrastructure through reproducible definitions.","tools":["Terraform","OpenTofu","Pulumi","Ansible","CloudFormation","Bicep","Chef","Puppet","Crossplane","Packer"]},{"id":"cloud-serverless-platform-engineering","name":"Serverless & Platform Engineering","description":"Managed execution, internal developer platforms, and deployment services.","tools":["AWS Lambda","Azure Functions","Cloud Functions","Cloud Run","Backstage","Cloud Foundry","Heroku","Netlify","Fly.io","Vercel"]},{"id":"cloud-networking-web-servers","name":"Networking & Web Servers","description":"Web serving, traffic management, enterprise networking, and inspection.","tools":["Nginx","Apache HTTP","HAProxy","F5","Cisco","Juniper","Fortinet","Wireshark","Envoy","Traefik"]},{"id":"cloud-operating-systems-virtualization","name":"Operating Systems & Virtualization","description":"Operating systems, hypervisors, and compute virtualization.","tools":["Linux","Ubuntu","Red Hat","Windows Server","VMware","Hyper-V","Nutanix","Proxmox","KVM","VirtualBox"]}]},{"id":"delivery","stage":5,"verb":"DELIVER","name":"Delivery & Reliability","tagline":"Ship safely, keep it healthy","cvar":"var(--c-del)","hex":"#ff5f9a","cats":[{"id":"delivery-devops-ci-cd","name":"DevOps & CI/CD","description":"Version control, build automation, release pipelines, and GitOps.","tools":["Git","GitHub","GitLab","Bitbucket","Jenkins","GitHub Actions","CircleCI","Azure DevOps","Argo CD","Flux"]},{"id":"delivery-artifacts-supply-chain","name":"Artifacts & Supply Chain","description":"Artifact repositories and software supply-chain assurance.","tools":["JFrog","Nexus","Harbor","Docker Hub","Artifact Registry","Amazon ECR","Sigstore","Syft","Renovate","Dependabot"]},{"id":"delivery-testing-qa","name":"Testing & QA","description":"Functional, API, mobile, and performance validation.","tools":["Selenium","Cypress","Playwright","Postman","JUnit","TestNG","pytest","JMeter","k6","Appium"]},{"id":"delivery-security-devsecops","name":"Security & DevSecOps","description":"Identity, secrets, code scanning, cloud security, and threat defense.","tools":["Okta","HashiCorp Vault","SonarQube","Snyk","CrowdStrike","Palo Alto Networks","Wiz","Trivy","Burp Suite","Keycloak"]},{"id":"delivery-monitoring-observability","name":"Monitoring & Observability","description":"Metrics, logs, traces, incident alerting, and operational visibility.","tools":["Prometheus","Grafana","Datadog","New Relic","Splunk","ELK Stack","OpenTelemetry","Dynatrace","Jaeger","PagerDuty"]}]},{"id":"practices","stage":null,"verb":"FOUNDATION","name":"Practices & Emerging","tagline":"How teams work and what comes next","cvar":"var(--c-prac)","hex":"#b7a6d9","cats":[{"id":"practices-methodologies-practices","name":"Methodologies & Practices","description":"Delivery, engineering, operations, and financial practices.","tools":["Agile","Scrum","Kanban","SAFe","DevOps","SRE","ITIL 4","FinOps","GitOps","TDD/BDD"]},{"id":"practices-emerging-tech","name":"Emerging Tech","description":"Evolving technology fields and new application opportunities.","tools":["IoT","Edge Computing","AR/VR","Blockchain","Quantum Computing","Robotics","5G","Digital Twins","Web3","Green IT"]}]}],"briefs":{"archimate":["Open modelling language for describing enterprise architecture across business, application and technology layers.","Gives architects a shared vocabulary to show how business, software and infrastructure connect.","Model elements and relationships in a tool such as Archi, then create views for different stakeholders.",["Enterprise architecture maps","Application landscape views"]],"uml":["Standard visual language for modelling software structure and behaviour.","Common notation for explaining designs, from classes to sequences.","Draw the diagram types that fit the question, such as class, sequence or component diagrams.",["Sequence diagrams","Class models"]],"c4 model":["Approach to describing software architecture at four zoom levels: context, containers, components and code.","Keeps diagrams simple and consistent so different audiences see the right level of detail.","Start with a system context diagram, then zoom into containers and components as needed.",["Architecture documentation","Onboarding new engineers"]],"lucidchart":["Online diagramming tool for flowcharts, architecture and process maps.","Quick shared diagrams that connect to data and other documentation tools.","Pick a template, drag shapes, connect them and share the diagram for comments.",["Process flowcharts","Cloud architecture diagrams"]],"draw.io":["Free diagramming tool, also called diagrams.net, that runs in the browser or as a desktop app.","No cost, no account needed, and files can be stored in your own systems.","Open the editor, choose a template or blank canvas and save to a drive or repository.",["Network diagrams","Quick architecture sketches"]],"enterprise architect":["Sparx Systems' modelling tool for UML, BPMN, ArchiMate and requirements.","Supports detailed model-based design with traceability from requirements to implementation.","Create a repository, model across layers and generate documentation or code from models.",["Model-based systems design","Requirements traceability"]],"archi":["Free open-source tool for creating ArchiMate models.","Lightweight way to practise and share enterprise architecture modelling.","Install the desktop app, model elements and relationships and export views.",["ArchiMate diagrams","Architecture reviews"]],"mermaid":["Text-based diagramming language that turns simple markup into flowcharts and sequence diagrams.","Diagrams live as text next to code, so they are versioned and easy to update.","Write diagram code in a markdown file or editor and render it in docs or repositories.",["Diagrams in documentation","Sequence flows in pull requests"]],"bpmn":["Standard notation for modelling business processes as flowcharts.","Gives business and IT a common picture of how a process works before it is automated.","Draw start events, tasks, gateways and end events in a modelling tool and review with stakeholders.",["Process mapping","Workflow automation design"]],"miro":["Online whiteboard for workshops, diagrams and planning.","Lets distributed teams brainstorm and map ideas together in real time.","Start from a template, add sticky notes and shapes, and invite participants to the board.",["Workshops and retros","Journey and process mapping"]],"figma":["Collaborative browser-based design tool for interfaces and prototypes.","Designers, developers and product people work on the same file at the same time.","Design screens with components, build clickable prototypes, and share links for feedback and developer handoff.",["UI design systems","Clickable prototypes"]],"sketch":["Mac design app for user interfaces and icons.","Established vector design tool with a large plugin library.","Design with symbols and shared libraries, then export assets or share through the web.",["App interface design","Icon sets"]],"adobe xd":["Adobe's earlier tool for designing and prototyping interfaces, now in maintenance mode.","Still found in existing projects and teams that adopted Adobe's design stack.","Open existing files, design artboards and prototypes, and migrate to another tool when needed.",["Legacy design files","Simple prototypes"]],"storybook":["Tool for building and documenting user interface components in isolation.","Gives teams a living catalogue of components and catches visual issues early.","Write a story for each component state, run it in the browser and publish it for others.",["Component library","Visual regression testing"]],"zeplin":["Handoff tool that turns designs into specs, assets and style guides for developers.","Cuts back-and-forth by giving developers exact sizes, colours and assets.","Connect your design tool, publish screens, and developers inspect specs and download assets.",["Design-to-code handoff","Style guide sharing"]],"framer":["Design and publishing tool for interactive sites and prototypes.","Lets designers publish real, responsive websites without a separate build step.","Lay out pages visually, add interactions and publish to a custom domain.",["Marketing websites","Interactive prototypes"]],"canva":["Online design tool with templates for graphics, presentations and social content.","Non-designers can produce polished visuals quickly.","Pick a template, edit text and images, and export or share.",["Social media graphics","Presentations"]],"invision":["Earlier prototyping and design collaboration platform.","Lets teams review clickable prototypes and gather feedback, though many have moved to newer tools.","Upload screens, link hotspots into a prototype and share for comments.",["Legacy prototypes","Design review"]],"penpot":["Open-source design and prototyping tool using web standards such as SVG.","Free, self-hostable alternative that gives designers and developers a common format.","Design in the browser, build components and export code-friendly assets.",["Open-source design workflows","Design systems"]],"lottie":["Format and libraries for lightweight vector animations exported from design tools.","Delivers smooth animation in apps and sites with small file sizes.","Export an animation as JSON from After Effects or a design tool and play it with a Lottie library.",["Animated icons","Onboarding animations"]],"jira":["Atlassian's tool for planning and tracking work items, widely used by software teams.","Gives teams one backlog with boards, workflows and reports to see progress and blockers.","Create a project, define a workflow, plan sprints on a board and review reports.",["Sprint planning","Bug and issue tracking"]],"confluence":["Team wiki and documentation space from Atlassian.","Keeps decisions, requirements and how-to guides in one searchable place linked to work items.","Create spaces and pages from templates, link them to Jira and keep them current.",["Product requirements","Runbooks and team knowledge"]],"slack":["Chat platform organised into channels, with integrations and workflows.","Moves team conversation out of email and puts alerts and updates next to the discussion.","Create channels by topic, connect tools such as Jira or monitoring, and use threads to stay organised.",["Incident coordination","Team and project channels"]],"microsoft teams":["Microsoft's collaboration app for chat, meetings, calls and shared files.","Bundles communication with Microsoft 365 documents and apps in one workspace.","Create teams and channels, hold meetings, co-author files and add apps as tabs.",["Meetings and calls","Project team channels"]],"trello":["Simple card and board tool for organising tasks.","Easy to learn, so small teams can visualise work without heavy process.","Create a board, add lists such as To do and Done, then move cards as work progresses.",["Small team task boards","Content calendars"]],"asana":["Work management tool for projects, tasks and goals.","Helps teams see who is doing what by when, across projects and departments.","Create projects with tasks and owners, use timeline and board views, and set up rules to automate routine steps.",["Marketing campaign planning","Cross-team project tracking"]],"notion":["Flexible workspace combining notes, documents, databases and simple project tools.","One place for docs, wikis and lightweight tracking that teams can shape to their needs.","Build pages and databases, link them together and share with teammates.",["Team wiki","Lightweight project tracker"]],"monday.com":["Work management platform with customisable boards and automations.","Gives non-technical teams a visual way to run projects and processes.","Pick a board template, define columns and statuses, and add automations and dashboards.",["Sales pipeline boards","Operations tracking"]],"sharepoint":["Microsoft platform for intranets, document libraries and team sites.","Stores and shares content with permissions and version history inside Microsoft 365.","Create a site, set up libraries and permissions, and connect it to Teams and Power Platform.",["Company intranet","Controlled document libraries"]],"sap":["Enterprise software suite for finance, supply chain, manufacturing and HR, best known for its ERP systems.","Gives a large business one system of record, so finance, logistics and HR work from the same data.","Consultants configure standard modules, migrate master data and connect other systems, usually in phases by business unit.",["Order-to-cash and procure-to-pay","Financial close and group reporting"]],"oracle fusion":["Oracle's cloud suite of ERP, HR, supply chain and procurement applications.","Runs core back-office processes as a cloud service that is updated on a regular cycle.","Configure modules per business unit, load master data, then integrate through APIs and integration tooling.",["Global finance consolidation","Payroll and talent management"]],"salesforce":["Cloud CRM platform for sales, service and marketing that can be extended with custom apps.","Keeps every customer interaction in one place and lets teams automate sales and support processes.","Set up objects and workflows with clicks, extend with code where needed, and connect data through APIs.",["Sales pipeline tracking","Customer support case management"]],"workday":["Cloud applications for HR, payroll, planning and finance.","One cloud system for people and money data, with built-in reporting for workforce decisions.","Deploy in waves: configure HR and payroll first, then finance, with integrations to banks and other systems.",["Hire-to-retire HR processes","Headcount and budget planning"]],"dynamics 365":["Microsoft's family of business applications covering CRM and ERP.","Fits organisations already on Microsoft tools and links sales, service and finance data to Office and Power Platform.","Choose the modules you need, configure them, and extend with Power Platform or custom code.",["Customer service desk","Finance and supply chain for mid to large firms"]],"servicenow":["Workflow platform best known for IT service management and now used across HR, security and operations.","Turns requests and incidents into tracked, automated workflows with a single view of work.","Configure catalogs, forms and flows on the platform, then integrate monitoring and asset data.",["IT incident and change management","Employee onboarding workflows"]],"netsuite":["Oracle's cloud ERP and financials suite aimed at growing and mid-sized companies.","Replaces spreadsheets and disconnected tools with one system for accounting, inventory and orders.","Implement core financials first, add inventory, CRM and e-commerce modules as the business grows.",["Multi-entity accounting","Inventory and order management"]],"zendesk":["Customer support platform for tickets, chat, a help centre and reporting.","Gives support teams a shared queue and customers self-service answers.","Connect email and chat channels, create ticket rules, publish help articles, then track response metrics.",["Email and chat support desk","Self-service knowledge base"]],"freshservice":["Cloud IT service management tool for incidents, requests, assets and changes.","Lighter and quicker to roll out than heavy ITSM suites, which suits smaller IT teams.","Enable the service catalog, set up ticket workflows and SLAs, and import assets.",["Internal IT helpdesk","Asset tracking"]],"bmc helix":["ITSM and operations suite from BMC covering service desk, discovery and AIOps.","Offers an enterprise-scale service management and operations platform with automation and analytics.","Roll out service management first, then add discovery, monitoring integration and automation.",["Enterprise service desk","Event correlation across IT operations"]],"power platform":["Microsoft's low-code family: Power Apps, Power Automate, Power BI and Copilot Studio.","Lets business teams build apps, automations and reports without waiting for a full development team.","Start from templates or Excel and SharePoint data, add connectors, and govern through environments.",["Internal approval apps","Departmental dashboards"]],"outsystems":["Low-code platform for building enterprise web and mobile applications.","Speeds up delivery of custom apps while keeping an application lifecycle with testing and deployment.","Model screens, logic and data visually, extend with code, and publish through managed environments.",["Customer portals","Process-heavy internal apps"]],"mendix":["Low-code application platform for building and deploying business apps.","Shortens the path from idea to a working app and encourages collaboration between business and IT.","Design data and pages in a visual studio, iterate with users, and deploy to cloud or on-premise.",["Field service apps","Workflow tools for operations"]],"appian":["Low-code platform focused on process automation and case management.","Combines workflow, data and automation so complex, rule-driven processes can be built and changed quickly.","Model the process, design forms and rules, connect systems, and monitor cases.",["Claims and case handling","Regulated approval processes"]],"uipath":["Robotic process automation platform that automates repetitive tasks across applications.","Frees people from manual copy-and-paste work, especially where systems have no API.","Record or design workflows, run them with software robots, and monitor them in an orchestrator.",["Invoice data entry","Cross-system data reconciliation"]],"automation anywhere":["Automation platform for software robots and AI-assisted business processes.","Automates high-volume rule-based work across legacy and modern applications.","Build bots in a visual designer, deploy them through a control room and track results.",["Back-office processing","Customer record updates"]],"zapier":["No-code service that connects web apps so an event in one triggers actions in another.","Gets simple integrations running in minutes without engineering effort.","Pick a trigger app, add one or more action steps, test and switch the automation on.",["Send form leads to a CRM","Post alerts to chat"]],"n8n":["Open-source workflow automation tool with a visual editor, which can be self-hosted.","Gives more control over data and logic than purely hosted tools, with room for custom code.","Drag nodes onto a canvas, connect apps and APIs, and run it on your own server or in the cloud.",["Data sync between systems","AI-assisted workflows"]],"make":["Visual automation platform for building multi-step workflows across apps.","Handles branching and data transformation more flexibly than simple trigger-action tools.","Design a scenario with modules on a canvas, map data between them and schedule it.",["Order processing flows","Content publishing pipelines"]],"power automate":["Microsoft's tool for automating workflows across Microsoft 365 and hundreds of other services.","Natural choice for Microsoft-based organisations, covering both cloud flows and desktop automation.","Build a flow from a template, choose triggers and actions, and share it with a team.",["Approval flows","Automatic file and email handling"]],"microsoft 365":["Subscription suite of Office apps, email, cloud storage and collaboration services.","Standard productivity base for many organisations, tied to identity and device management.","Provision users and licences through the admin centre, then secure and govern the tenant.",["Email and calendar","Shared documents and meetings"]],"google workspace":["Google's suite of Gmail, Docs, Drive, Calendar and Meet for organisations.","Cloud-first collaboration with real-time document editing and simple administration.","Set up a domain, create users, configure sharing and security policies in the admin console.",["Co-authoring documents","Company email and calendars"]],"intune":["Microsoft's cloud service for managing devices and apps.","Lets IT enforce security settings on laptops and phones, including personal devices at work.","Enrol devices, define compliance and configuration policies, and deploy apps.",["Mobile device management","Laptop compliance"]],"jamf":["Device management platform focused on Apple devices.","Gives Apple fleets the setup and security controls that generic tools handle less well.","Enrol Macs and iPhones automatically, apply configuration profiles and deploy software.",["Mac fleet management","Zero-touch laptop setup"]],"entra id":["Microsoft's cloud identity service, formerly Azure Active Directory.","Central sign-in and access control for apps, with multi-factor authentication and conditional access.","Add users and groups, connect applications for single sign-on and set conditional access rules.",["Single sign-on","Multi-factor authentication"]],"zoom":["Video meeting and webinar platform.","Reliable video calls and webinars for distributed teams and external audiences.","Schedule meetings, share screens, record sessions and integrate with calendars.",["Team meetings","Webinars"]],"citrix":["Virtual app and desktop delivery for secure remote work.","Lets people use corporate apps and desktops from any device while data stays in the data centre or cloud.","Publish apps or desktops from a delivery platform and give users access through a client or browser.",["Remote desktops","Secure access to legacy apps"]],"workspace one":["VMware's platform for managing devices and delivering apps to employees.","One console for endpoint management, app access and security.","Enrol devices, assign apps and policies, and connect identity for single sign-on.",["Unified endpoint management","Employee app catalog"]],"webex":["Cisco's platform for meetings, calling and messaging.","Enterprise meeting rooms and calling with strong security options.","Schedule meetings, connect room devices and integrate with calendars and phones.",["Meeting rooms","Contact centre calling"]],"google meet":["Google's video meeting service, built into Workspace.","Starts a call straight from a calendar invite with no separate app needed.","Create a meeting from Calendar or Gmail and share the link.",["Quick team calls","Meetings with captions"]],"python":["General-purpose language known for readable code and a huge ecosystem.","Fast to write and strong in automation, web back ends, data work and machine learning.","Install Python, use virtual environments and pip, and start with scripts before frameworks such as Django or FastAPI.",["Data analysis and machine learning","Automation scripts and APIs"]],"java":["Mature, statically typed language that runs on the Java Virtual Machine.","Reliable, fast and backed by a vast enterprise ecosystem, so it powers many large systems.","Learn the language and build tools such as Maven or Gradle, then frameworks like Spring Boot.",["Banking and enterprise back ends","Large-scale microservices"]],"javascript":["The language of the web browser, also used on servers through Node.js.","Runs everywhere users are, and it underpins nearly every web front end.","Practise in the browser console, learn the DOM and async code, then add a framework.",["Interactive web pages","Full-stack apps with Node.js"]],"typescript":["JavaScript with static types, compiled to plain JavaScript.","Catches mistakes before runtime and makes large codebases easier to change.","Add TypeScript to a JavaScript project, start with loose settings and tighten types gradually.",["Large web applications","Typed APIs and shared types"]],"c#":["Modern, object-oriented language from Microsoft that runs on .NET.","Productive for business apps, web services, games and Windows software.","Install the .NET SDK, create a console app, then move to ASP.NET Core or Unity.",["Enterprise web APIs","Game development with Unity"]],"c++":["High-performance language that gives control over memory and hardware.","Used where speed and resource control matter, such as engines, trading and embedded systems.","Learn modern C++ with a current standard, use a build system such as CMake and practise memory safety habits.",["Game engines","Embedded and real-time systems"]],"go":["Simple, compiled language from Google designed for concurrent network services.","Fast builds, small binaries and easy concurrency make it popular for cloud and infrastructure tools.","Install Go, learn goroutines and channels, and build a small HTTP service.",["Cloud-native services","Command-line and infrastructure tools"]],"rust":["Systems language focused on memory safety and performance without a garbage collector.","Prevents whole classes of bugs while staying as fast as C and C++.","Work through the Rust book, learn ownership and borrowing, and build small tools with Cargo.",["Performance-critical services","Secure systems components"]],"kotlin":["Modern language for the JVM, the preferred language for Android development.","More concise and safer than Java while staying fully interoperable with it.","Start with Android Studio or IntelliJ, learn null safety and coroutines, then build an app or server.",["Android apps","Server-side services with Spring"]],"swift":["Apple's language for building iOS, macOS and other Apple platform apps.","Safe, fast and designed for Apple's frameworks such as SwiftUI.","Install Xcode, learn Swift basics in a playground, then build a small SwiftUI app.",["iPhone and iPad apps","macOS utilities"]],"php":["Server-side scripting language that powers a large share of websites.","Quick to deploy and the foundation of WordPress and many content and commerce sites.","Run PHP locally, learn modern PHP, then use a framework such as Laravel.",["Content websites","E-commerce back ends"]],"ruby":["Dynamic language designed for programmer happiness, best known through Ruby on Rails.","Lets small teams build web products quickly with expressive code.","Install Ruby, learn the basics, then build a small Rails application.",["Startup web apps","Scripting and tooling"]],"scala":["Language for the JVM that mixes object-oriented and functional programming.","Expressive for data processing and concurrent systems, and it is the language behind Apache Spark.","Use sbt to start a project, learn case classes and collections, and write a Spark job.",["Big data jobs with Spark","Concurrent back-end services"]],"r":["Language and environment for statistical computing and graphics.","Excels at statistics, analysis and publication-quality charts, and is common in research and analytics.","Install R and RStudio, load data frames, and use packages such as tidyverse and ggplot2.",["Statistical analysis","Research reports and charts"]],"html5":["Current standard markup language that structures content on the web.","Every web page is built on it, and good structure helps accessibility and search.","Write semantic elements such as header, nav and main, and validate your pages.",["Web page structure","Forms and media embedding"]],"css3":["Style language that controls layout, colour and typography on the web.","Separates appearance from content and enables responsive design.","Learn the box model, flexbox and grid, and use media queries for different screen sizes.",["Responsive layouts","Themes and animation"]],"react":["JavaScript library for building user interfaces from reusable components.","Large ecosystem and a component model that keeps complex interfaces organised.","Create a project with a tool such as Vite, build components, and manage state with hooks.",["Single-page applications","Dashboards"]],"angular":["Full front-end framework from Google using TypeScript.","Provides routing, forms, dependency injection and tooling out of the box, which suits large teams.","Use the Angular CLI to scaffold an app and build components, services and modules.",["Enterprise web applications","Large internal portals"]],"vue.js":["Approachable progressive framework for building web interfaces.","Gentle learning curve and good documentation make it quick to adopt.","Start from a CDN script or the create-vue tool, then build components and use Pinia for state.",["Interactive front ends","Gradually upgrading existing pages"]],"svelte":["Front-end framework that compiles components to small, fast JavaScript.","Less boilerplate and smaller bundles, since much of the work happens at build time.","Create a project with SvelteKit, write components in single files and deploy.",["Fast marketing sites","Interactive widgets"]],"next.js":["React framework that adds routing, server rendering and full-stack features.","Handles performance and search-friendliness concerns that plain React leaves to you.","Create an app with the Next.js tool, add pages or routes and choose server or static rendering.",["SEO-friendly websites","Full-stack React apps"]],"tailwind css":["Utility-first CSS framework with small classes composed directly in markup.","Speeds up styling and keeps designs consistent without writing much custom CSS.","Install it in your build, add utility classes to elements and configure a theme.",["Rapid prototyping","Design-system styling"]],"bootstrap":["Popular CSS framework with ready-made responsive components and grid.","Gets a clean, responsive layout running quickly with familiar patterns.","Include Bootstrap, use the grid and components such as navbar and cards, and customise variables.",["Admin dashboards","Quick responsive sites"]],"vite":["Fast build tool and development server for modern web projects.","Near-instant start and quick updates in development keep feedback loops short.","Run the Vite create command, pick a framework template and start the dev server.",["Front-end project tooling","Library builds"]],"android":["Google's mobile operating system and app platform.","Reaches the largest number of smartphones worldwide.","Install Android Studio, create a project in Kotlin and run it on an emulator or device.",["Consumer mobile apps","Device-specific apps"]],"ios":["Apple's operating system for iPhone, with its own app platform.","Reaches Apple's user base, which is valuable for many consumer and business apps.","Use Xcode and Swift, test in the simulator and publish through the App Store.",["iPhone apps","Mobile-first services"]],"flutter":["Google's toolkit for building apps for mobile, web and desktop from one Dart codebase.","One team can ship to several platforms with a consistent look and fast rendering.","Install the Flutter SDK, create a project and build widgets, then run on a device.",["Cross-platform mobile apps","Prototype-to-product apps"]],"react native":["Framework for building native mobile apps with React and JavaScript.","Lets web teams reuse skills and share code across iOS and Android.","Start with Expo or the CLI, build screens from components and run on devices.",["Cross-platform apps","Mobile versions of web products"]],"swiftui":["Apple's declarative framework for building interfaces across its platforms.","Less code for modern Apple interfaces and shared layouts across iPhone, iPad and Mac.","Open Xcode, create a SwiftUI project and compose views with modifiers and state.",["Modern iOS interfaces","Widgets and Apple Watch apps"]],"jetpack compose":["Android's modern declarative toolkit for building native interfaces in Kotlin.","Less code than older view systems and easier to keep in sync with state.","Create a Compose project in Android Studio and build composable functions.",["Modern Android interfaces","Reusable UI components"]],".net maui":["Microsoft's framework for building cross-platform apps for mobile and desktop with C#.","Lets .NET teams target Android, iOS, Windows and macOS from one codebase.","Install the MAUI workload for .NET, create a project and run on an emulator.",["Business apps on multiple devices","Reuse of .NET code"]],"ionic":["Framework for building mobile and web apps using web technologies.","Web developers can build mobile apps with the tools they already know.","Create a project with the Ionic CLI, choose Angular, React or Vue and package with Capacitor.",["Hybrid mobile apps","Progressive web apps"]],"kotlin multiplatform":["Technology for sharing Kotlin code across Android, iOS, web and server.","Shares business logic while keeping native interfaces where it matters.","Add shared modules to a project and use them from Android and iOS apps.",["Shared networking and data logic","Gradual cross-platform adoption"]],"expo":["Toolkit and services around React Native that simplify building and shipping apps.","Removes much native setup, with easy testing on a phone and cloud builds.","Run the create command, start the dev server, scan a QR code to preview and build with Expo services.",["Rapid mobile prototypes","Production React Native apps"]],"node.js":["JavaScript runtime that runs code outside the browser, commonly for servers.","Lets teams use one language across front end and back end, with a huge package ecosystem.","Install Node, create a project with npm and build an HTTP service with a framework such as Express.",["APIs and web servers","Real-time apps"]],"spring boot":["Java framework that makes it fast to create production-ready applications and services.","Provides sensible defaults, embedded servers and a large ecosystem for enterprise Java.","Generate a project with Spring Initializr, add dependencies and run it as a jar.",["Java microservices","Enterprise REST APIs"]],".net":["Microsoft's cross-platform framework for building web, desktop, cloud and mobile apps.","Mature tooling and strong performance, especially for C# teams in enterprise settings.","Install the SDK, create a project with the dotnet command and use ASP.NET Core for web services.",["Enterprise web APIs","Windows and cloud applications"]],"django":["High-level Python web framework with batteries included.","Ships with an admin, ORM and security features so teams build quickly.","Start a project with django-admin, define models, and use the built-in admin and views.",["Content and data-driven sites","Internal tools"]],"fastapi":["Modern Python framework for building APIs with type hints and automatic documentation.","Fast to develop, validates data automatically and generates interactive API docs.","Install it with an ASGI server, define typed endpoints and open the generated docs page.",["Machine learning model APIs","Lightweight microservices"]],"flask":["Lightweight Python web framework that stays small and flexible.","Easy to understand and good when you want to choose your own components.","Create an app file, add routes and run it locally, then add extensions as needed.",["Small web apps","Prototype APIs"]],"express.js":["Minimal web framework for Node.js.","Simple routing and middleware that is the base for many Node back ends.","Install Express, define routes and middleware and listen on a port.",["REST APIs","Backend for single-page apps"]],"nestjs":["Structured Node.js framework using TypeScript and modular architecture.","Brings Angular-like structure to back ends, which helps larger teams stay consistent.","Use the Nest CLI to create modules, controllers and providers.",["Enterprise Node services","Typed REST and GraphQL APIs"]],"laravel":["PHP framework with expressive syntax and a rich set of built-in features.","Makes PHP development enjoyable and productive, with authentication, queues and more included.","Create a project with Composer, define routes and use Eloquent for database access.",["Web applications","Subscription and SaaS back ends"]],"ruby on rails":["Full-stack web framework for Ruby that favours convention over configuration.","Lets small teams build complete database-backed web apps quickly.","Generate an app with the rails command, scaffold models and views and run migrations.",["Startup web products","Internal business apps"]],"rest":["Architectural style for web APIs that uses HTTP verbs on resources.","Simple, widely understood and supported by every language and tool.","Design resources as nouns, use GET, POST, PUT and DELETE and return clear status codes.",["Public and internal APIs","Mobile app back ends"]],"graphql":["Query language for APIs that lets clients ask for exactly the data they need.","Reduces over- and under-fetching and gives front-end teams flexibility.","Define a schema, write resolvers and query it from clients with a tool such as Apollo.",["Data-rich mobile and web apps","Aggregating several back ends"]],"grpc":["High-performance remote procedure call framework using Protocol Buffers.","Fast, strongly typed communication between services, with generated client code.","Define services in a proto file, generate code and implement servers and clients.",["Service-to-service communication","Streaming data between components"]],"openapi":["Standard format for describing REST APIs in a machine-readable file.","Becomes the shared contract for documentation, testing and code generation.","Write or generate a spec, publish docs from it and use it to generate clients.",["API documentation","Contract-first design"]],"kong":["API gateway that manages, secures and monitors API traffic.","Centralises authentication, rate limiting and routing in front of services.","Run Kong, register services and routes and enable plugins such as authentication.",["Securing APIs","Traffic control for microservices"]],"apigee":["Google Cloud's API management platform.","Gives enterprises security, analytics and a developer portal for their APIs.","Create API proxies, apply policies and publish products to developers.",["API monetisation","Partner API programs"]],"mulesoft":["Salesforce's platform for connecting applications, data and devices through APIs.","Provides a structured way to integrate many systems with reusable assets.","Design APIs, build integration flows in Anypoint Studio and manage them in the platform.",["Enterprise integration","API-led connectivity"]],"wso2":["Open-source integration and API management products.","Offers API gateway, identity and integration in one open stack.","Install a WSO2 product, publish APIs and add policies.",["API gateways","Open-source integration"]],"apache camel":["Open-source integration framework that implements well-known enterprise integration patterns.","Routes and transforms messages between systems with little code.","Define routes in Java or YAML that connect components such as HTTP, Kafka and files.",["System-to-system integration","Message routing"]],"boomi":["Cloud integration platform for connecting applications, data and APIs.","Low-code integration that lets teams connect systems quickly.","Build integration processes in a visual designer and deploy them to runtimes.",["SaaS app integration","Data synchronisation"]],"vs code":["Free, extensible code editor from Microsoft.","Fast, runs everywhere and has extensions for nearly every language and tool.","Install it, add language extensions and use the built-in terminal and Git support.",["Everyday coding","Remote and container development"]],"intellij idea":["JetBrains IDE for Java and Kotlin with deep code understanding.","Smart refactoring and navigation save time on large codebases.","Open a Maven or Gradle project, let it index and use code inspections and debugging.",["Java development","Large refactorings"]],"visual studio":["Microsoft's full IDE for .NET, C++ and Windows development.","Rich debugging, profiling and project tools for complex Microsoft stack projects.","Install the workloads you need, open a solution and use the debugger and test tools.",["C# and .NET development","Windows applications"]],"eclipse":["Long-standing open-source IDE, especially for Java.","Free and extensible, and still present in many enterprise environments.","Install Eclipse for your language, import a project and add plugins.",["Java development","Embedded tooling"]],"pycharm":["JetBrains IDE for Python.","Provides debugging, testing and framework support for Python projects.","Create or open a project, set up an interpreter and use run configurations.",["Python application development","Data science projects"]],"android studio":["Google's official IDE for Android app development.","Includes emulators, layout tools and profilers made for Android.","Install it, create a project, and run it on an emulator or connected phone.",["Building Android apps","Testing on virtual devices"]],"xcode":["Apple's IDE for building apps for iOS, macOS and other Apple platforms.","Required for building, signing and publishing Apple platform apps.","Install from the Mac App Store, create a project and run it in a simulator.",["Building iPhone apps","Profiling app performance"]],"maven":["Build and dependency management tool for Java projects.","Standard project structure and dependency handling that most Java teams know.","Describe the project in a pom file and run commands such as package and test.",["Building Java applications","Managing dependencies"]],"gradle":["Flexible build tool for Java, Kotlin and Android projects.","Fast incremental builds and scripts that can be customised.","Add a build script, declare dependencies and run tasks with the Gradle wrapper.",["Android builds","Multi-module projects"]],"npm":["Package manager and registry for JavaScript.","Gives access to a vast library of open-source packages and manages project dependencies.","Run npm init, install packages and use scripts defined in package.json.",["Installing libraries","Running project scripts"]],"mysql":["Popular open-source relational database.","Easy to run, well understood and widely hosted, so it suits many web workloads.","Install or use a managed service, create schemas and tables, and tune indexes for your queries.",["Web application databases","Content management back ends"]],"postgresql":["Advanced open-source relational database with rich SQL and extension support.","Reliable, standards-compliant and flexible, with JSON, geospatial and vector extensions.","Run it locally or managed, design tables with constraints and add extensions as needed.",["General-purpose application database","Analytics and geospatial data"]],"oracle db":["Enterprise relational database from Oracle.","Strong performance, high availability and features for mission-critical systems.","Provision with DBAs or Oracle Cloud, design schemas and use PL/SQL for server logic.",["Core banking and ERP","Large transactional systems"]],"sql server":["Microsoft's relational database platform.","Integrates tightly with Windows, .NET and Power BI, and is common in enterprises.","Install or use Azure SQL, manage with SQL Server Management Studio and write T-SQL.",["Line-of-business apps","Data warehouses on the Microsoft stack"]],"mariadb":["Open-source relational database forked from MySQL.","Community-driven and largely MySQL compatible, with extra storage engines.","Install it as a drop-in alternative and migrate MySQL schemas and data.",["MySQL replacement","Web hosting databases"]],"sqlite":["Tiny, serverless SQL database stored in a single file.","Zero setup and ideal for embedded and local storage.","Open a database file from your app library and run SQL directly.",["Mobile and desktop app storage","Prototyping and testing"]],"ibm db2":["IBM's relational database family.","Proven for large, high-volume transaction and analytics workloads, especially on IBM systems.","Deploy on-premises or on IBM Cloud and manage with Db2 tooling.",["Mainframe-linked enterprise systems","Large data warehouses"]],"amazon aurora":["AWS's cloud-built relational database compatible with MySQL and PostgreSQL.","Higher throughput and managed availability than standard managed databases.","Create an Aurora cluster, point your app at the endpoint and scale replicas.",["High-traffic SaaS back ends","Migrating from commercial databases"]],"azure sql":["Microsoft's managed SQL Server database service in Azure.","No server patching or backups to run, with built-in scaling and security.","Create a database in the Azure portal, connect with standard SQL tools and set firewall rules.",["Cloud migration of SQL Server apps","Serverless app databases"]],"cloud sql":["Google Cloud's managed MySQL, PostgreSQL and SQL Server service.","Offloads backups, updates and failover to Google.","Create an instance, connect through the proxy and configure backups.",["Managed app databases","Lift-and-shift migration"]],"mongodb":["Document database storing flexible JSON-like records.","Schema flexibility and easy scaling suit changing data models.","Run it locally or in Atlas, store documents in collections and add indexes.",["Product catalogs","Content and user profile stores"]],"redis":["In-memory data store used for caching and fast data structures.","Microsecond responses take load off your main database.","Start a Redis server, cache key-value pairs with expiry and use lists or streams as needed.",["Caching","Session storage and leaderboards"]],"cassandra":["Distributed wide-column database built for huge scale and availability.","Handles massive write volumes across data centres with no single point of failure.","Model tables around queries, set replication across nodes and tune consistency.",["Time-series and event data","Always-on global services"]],"dynamodb":["AWS's fully managed key-value and document database.","Single-digit millisecond performance at any scale with no servers to manage.","Design tables around access patterns, choose partition keys and set capacity mode.",["Serverless application data","High-scale session and order data"]],"elasticsearch":["Distributed search and analytics engine.","Fast full-text search and aggregations over large volumes of data.","Index documents, define mappings and query through its REST API.",["Site and product search","Log analytics"]],"neo4j":["Graph database storing data as nodes and relationships.","Makes connected-data questions simple and fast.","Model entities as nodes and relationships and query with Cypher.",["Recommendation engines","Fraud and network analysis"]],"couchbase":["Distributed NoSQL database with document storage and built-in caching.","Combines key-value speed with SQL-like queries and mobile sync.","Create buckets, store JSON documents and query with SQL++.",["Interactive web and mobile apps","Offline-capable mobile sync"]],"cosmos db":["Microsoft's globally distributed multi-model database.","Turnkey global replication with guaranteed latency and several APIs.","Create an account, choose an API such as NoSQL and select regions.",["Global applications","Low-latency IoT data"]],"influxdb":["Database designed for time-series data.","Efficient storage and queries for metrics and sensor readings.","Write timestamped points and query with Flux or SQL, with retention policies.",["Metrics and monitoring","IoT sensor data"]],"opensearch":["Open-source search and analytics suite forked from Elasticsearch.","Open licensing with search, log analytics and dashboards.","Deploy a cluster or use AWS-managed service, index data and visualise with Dashboards.",["Log analytics","Application search"]],"kafka":["Distributed event streaming platform.","Durable, high-throughput streams decouple producers from consumers.","Create topics, publish events with producers and read them with consumer groups.",["Event-driven microservices","Real-time data pipelines"]],"rabbitmq":["Message broker that routes messages between applications.","Reliable queuing with flexible routing for background work.","Declare exchanges and queues, publish messages and acknowledge them in consumers.",["Background job queues","Service decoupling"]],"activemq":["Open-source message broker from Apache supporting JMS.","Fits Java enterprise messaging and many protocols.","Run a broker, define queues or topics and connect JMS clients.",["Enterprise Java messaging","Legacy integration"]],"pulsar":["Distributed messaging and streaming platform with multi-tenancy.","Combines queuing and streaming with separate compute and storage layers.","Create tenants and topics, then publish and subscribe with client libraries.",["Multi-tenant messaging","Geo-replicated streams"]],"amazon sqs":["AWS's managed message queue service.","Simple, scalable queuing with no servers to operate.","Create a queue, send messages and process them with workers or Lambda.",["Decoupling microservices","Job buffering"]],"azure service bus":["Microsoft's managed enterprise messaging service.","Reliable queues and topics with features such as sessions and dead-lettering.","Create a namespace, define queues or topics and use the SDKs.",["Enterprise integration","Ordered message processing"]],"google pub/sub":["Google Cloud's managed publish and subscribe messaging service.","Global, scalable messaging that works well with Google data services.","Create topics and subscriptions, then publish and pull or push messages.",["Event ingestion","Streaming into BigQuery"]],"nats":["Lightweight, high-performance messaging system.","Very low latency and simple operations for cloud-native systems.","Run a NATS server, connect clients and use subjects for publish and subscribe.",["Microservice messaging","Edge and IoT communication"]],"flink":["Stream processing framework for stateful, real-time computations.","Accurate, low-latency processing of continuous data.","Write jobs with its APIs, define windows and state, then deploy to a cluster.",["Real-time analytics","Fraud detection streams"]],"kinesis":["AWS service for collecting and processing streaming data.","Managed streaming without running your own clusters.","Create a stream, put records from producers and read with consumers or Lambda.",["Clickstream ingestion","Real-time log pipelines"]],"apache spark":["Distributed engine for large-scale data processing.","Processes big data fast in memory with APIs in Python, SQL and Scala.","Write jobs in PySpark or SQL and run them on a cluster or managed service.",["Large-scale ETL","Machine learning on big data"]],"hadoop":["Framework for distributed storage and processing of big data.","Pioneered affordable large-scale data storage on commodity hardware.","Store data in HDFS and process it with tools such as Hive and MapReduce.",["Legacy data lakes","Batch processing at scale"]],"airflow":["Platform for authoring, scheduling and monitoring workflows.","Defines data pipelines as code with dependencies and retries.","Write DAGs in Python, schedule them and monitor runs in the UI.",["Data pipeline orchestration","Scheduled batch jobs"]],"dbt":["Tool for transforming data in the warehouse using SQL.","Brings software practices such as tests and version control to analytics.","Write SQL models, add tests and docs, then run dbt against your warehouse.",["Analytics engineering","Warehouse transformations"]],"databricks":["Unified data and AI platform built around Spark and lakehouse storage.","One place for data engineering, analytics and machine learning.","Create a workspace, attach notebooks to clusters and manage tables with Delta Lake.",["Lakehouse platforms","Large-scale ML"]],"snowflake":["Cloud data platform for warehousing and analytics.","Separates storage from compute so teams scale independently.","Load data into tables, size virtual warehouses and query with SQL.",["Enterprise data warehouse","Data sharing"]],"bigquery":["Google's serverless data warehouse.","Fast SQL on huge datasets without managing infrastructure.","Load or stream data, write SQL in the console and control costs with partitions.",["Large-scale analytics","ML on warehouse data"]],"redshift":["AWS's cloud data warehouse.","Fast analytics on structured data, closely tied to the AWS ecosystem.","Create a cluster or serverless workgroup, load from S3 and query with SQL.",["Business reporting","Data warehouse on AWS"]],"fivetran":["Managed service for automated data pipelines.","Moves data from apps and databases into a warehouse without custom code.","Choose a source connector and destination and let it sync on a schedule.",["SaaS data ingestion","Warehouse loading"]],"talend":["Data integration and quality platform.","Visual design of ETL jobs with data quality features.","Design jobs in the studio, connect sources and targets and schedule them.",["Enterprise ETL","Data cleansing"]],"power bi":["Microsoft's business intelligence and dashboard tool.","Affordable self-service analytics that fits the Microsoft ecosystem.","Connect data, build a model and visuals in Power BI Desktop and publish to the service.",["Executive dashboards","Self-service reporting"]],"tableau":["Visual analytics platform for exploring and sharing data.","Powerful, intuitive visualisation for analysts.","Connect to data, drag fields to build charts and publish dashboards.",["Interactive dashboards","Ad-hoc data exploration"]],"looker":["Google's BI platform based on a shared semantic data model.","Consistent metric definitions across the organisation.","Define models in LookML and let users explore and build dashboards.",["Governed metrics","Embedded analytics"]],"qlik":["Analytics platform with an associative data engine.","Lets users explore relationships across data freely.","Load data, build apps with charts and share them on Qlik Sense.",["Guided analytics","Operational dashboards"]],"superset":["Open-source data exploration and dashboarding platform.","Free, SQL-friendly BI for many databases.","Connect a database, create datasets and charts and assemble dashboards.",["Open-source BI","Embedded charts"]],"metabase":["Open-source BI tool that lets non-technical people ask questions of data.","Very easy to set up and use.","Connect a database, use the question builder and save dashboards.",["Simple team dashboards","Self-service questions"]],"excel":["Spreadsheet application used for analysis and modelling.","Familiar to nearly everyone and ideal for quick analysis.","Use tables, formulas and PivotTables, and connect to data with Power Query.",["Financial models","Quick ad-hoc analysis"]],"quicksight":["AWS's cloud business intelligence service.","Serverless dashboards with pay-per-session pricing.","Connect to data sources such as Athena or Redshift, build analyses and share dashboards.",["AWS data dashboards","Embedded analytics"]],"sisense":["Analytics platform focused on embedding insights into applications.","Lets products ship analytics to their own customers.","Connect data, build dashboards and embed them via its APIs.",["Embedded customer analytics","Product dashboards"]],"domo":["Cloud business intelligence platform with data integration.","Combines connectors, dashboards and apps in one place.","Connect data sources, build cards and dashboards and share with teams.",["Executive dashboards","Cross-department reporting"]],"tensorflow":["Google's open-source machine learning framework.","Mature tooling for training and deploying models at scale.","Build models with Keras, train on data and export for serving or mobile.",["Deep learning models","On-device ML"]],"pytorch":["Open-source deep learning framework popular in research.","Flexible, Pythonic and the default for much modern AI work.","Define models as Python classes, train with tensors and GPUs and export for serving.",["Research and training models","Fine-tuning large models"]],"scikit-learn":["Python library of classic machine learning algorithms.","Simple, consistent tools for common modelling tasks.","Load data, split into train and test sets, fit a model and evaluate it.",["Prediction on tabular data","Baseline models"]],"hugging face":["Hub and libraries for sharing and using machine learning models.","Gives quick access to thousands of pretrained models and datasets.","Download a model with the Transformers library and run or fine-tune it.",["Using open models","Model sharing"]],"langchain":["Framework for building applications around large language models.","Provides ready components for prompts, tools, retrieval and chains.","Install the library, connect a model and compose chains or retrievers.",["Retrieval-augmented chatbots","LLM workflows"]],"llamaindex":["Framework for connecting language models to your own data.","Simplifies indexing and retrieving documents for question answering.","Load documents, build an index and query it with a model.",["Document Q&A","Knowledge assistants"]],"mlflow":["Open-source platform for managing the machine learning lifecycle.","Tracks experiments and models so work is reproducible.","Log parameters and metrics during training and register models.",["Experiment tracking","Model registry"]],"kubeflow":["Machine learning toolkit for Kubernetes.","Runs ML pipelines and training on shared cluster infrastructure.","Install on Kubernetes, define pipelines and run training jobs.",["ML pipelines on Kubernetes","Scalable training"]],"openai":["AI company providing GPT models through an API.","Powerful general-purpose language and multimodal models.","Get an API key, call the API with prompts and add tools as needed.",["Chat assistants","Content generation"]],"claude":["Anthropic's family of AI models and assistants.","Strong reasoning, writing and coding with a focus on safety and long context.","Use the Claude API or apps, write clear prompts and add tools or documents.",["Coding assistance","Document analysis"]],"gemini":["Google's family of multimodal AI models.","Handles text, images, audio and video, with tight Google integration.","Use the Gemini API or Vertex AI and send multimodal prompts.",["Multimodal assistants","Workspace-integrated AI"]],"amazon bedrock":["AWS service for accessing foundation models through one API.","Choose among several models with AWS security and no infrastructure.","Enable models in your account and call them with the AWS SDK.",["Generative AI on AWS","Model comparison"]],"azure ai foundry":["Microsoft's platform for building and managing AI applications.","Brings models, tools and governance together on Azure.","Create a project, deploy a model and build and evaluate apps.",["Enterprise copilots","AI app governance"]],"vertex ai":["Google Cloud's machine learning and generative AI platform.","Unified tooling to train, deploy and manage models and use Gemini.","Open Vertex AI, choose a model or train your own and deploy to an endpoint.",["Managed ML pipelines","Generative AI apps"]],"pinecone":["Managed vector database.","Fast similarity search with minimal operations.","Create an index, upsert embeddings and query for nearest neighbours.",["Semantic search","Retrieval for AI assistants"]],"weaviate":["Open-source vector database with hybrid search.","Combines vector and keyword search with built-in modules.","Define a schema, import data and query with GraphQL or the client.",["Hybrid search","Knowledge retrieval"]],"milvus":["Open-source vector database built for scale.","Handles billions of vectors with multiple index types.","Deploy Milvus, create collections and insert and search vectors.",["Large-scale similarity search","Recommendations"]],"chroma":["Lightweight open-source embedding database.","Very easy to start with for prototypes.","Install the library, add documents and query by similarity.",["Prototype RAG apps","Local experiments"]],"pgvector":["PostgreSQL extension for storing and searching vectors.","Adds vector search to the database you may already run.","Enable the extension, add a vector column and query with distance operators.",["Vector search inside Postgres","Simple RAG backends"]],"qdrant":["Open-source vector database with filtering.","Fast search with rich payload filters and a simple API.","Run Qdrant, create a collection and upsert points with payloads.",["Filtered semantic search","RAG for assistants"]],"mcp":["Model Context Protocol, an open standard for connecting AI to tools and data.","One standard way for assistants to use many systems.","Run or install an MCP server and connect it to a compatible client.",["Tool access for assistants","Connecting enterprise data"]],"langgraph":["Framework for building stateful, multi-step agent workflows as graphs.","Gives control over loops, branches and state in agents.","Define nodes and edges, manage state and run the graph.",["Agent workflows","Human-in-the-loop flows"]],"crewai":["Framework for orchestrating teams of role-based AI agents.","Makes it simple to have agents collaborate on tasks.","Define agents with roles and tasks and run a crew.",["Multi-agent automation","Research workflows"]],"autogen":["Microsoft's framework for multi-agent conversations.","Lets agents talk to each other and use tools to solve tasks.","Define agents, set up a conversation and run it.",["Multi-agent problem solving","Code-writing agents"]],"aws":["Amazon's cloud platform with the broadest range of services.","Largest ecosystem, global reach and services for nearly any workload.","Create an account, use IAM for access, then start with compute, storage and networking.",["Hosting web apps","Data and AI platforms"]],"microsoft azure":["Microsoft's cloud platform.","Strong fit for Microsoft-centric enterprises, with hybrid and identity integration.","Create a subscription, organise resources in groups and deploy with the portal or CLI.",["Enterprise workloads","Hybrid cloud"]],"google cloud":["Google's cloud platform.","Strong in data, analytics, AI and Kubernetes.","Create a project, enable APIs and deploy with the console or gcloud.",["Data and AI workloads","Containerised apps"]],"oracle cloud":["Oracle's cloud infrastructure and applications platform.","Natural home for Oracle databases and applications.","Create a tenancy and compartments and deploy compute or Autonomous Database.",["Oracle workloads","Database-heavy systems"]],"ibm cloud":["IBM's hybrid cloud platform.","Supports regulated industries and mainframe-connected enterprises.","Create an account, use resource groups and deploy Red Hat OpenShift or services.",["Regulated workloads","Hybrid enterprise cloud"]],"alibaba cloud":["Cloud platform from Alibaba Group.","Strong presence in China and Asia-Pacific.","Create an account and choose regional services such as ECS and OSS.",["Asia-Pacific hosting","Cross-border e-commerce"]],"cloudflare":["Global network providing CDN, security and edge compute.","Speeds up and protects sites close to users.","Point DNS to Cloudflare, enable caching and security rules and deploy Workers.",["CDN and DDoS protection","Edge functions"]],"digitalocean":["Simple cloud provider for developers and small teams.","Straightforward pricing and an easy interface.","Create droplets or app platform apps and attach storage and networking.",["Small web apps","Developer sandboxes"]],"akamai":["Edge and cloud delivery and security provider.","Large global network for content delivery and security.","Configure delivery properties and security policies, or use Linode compute.",["Media delivery","Web security"]],"linode":["Developer-friendly cloud hosting, now part of Akamai.","Simple virtual machines at predictable prices.","Create a Linode instance, connect with SSH and deploy your app.",["Virtual servers","Hosted web apps"]],"docker":["Platform for packaging applications into containers.","Makes apps run the same everywhere.","Write a Dockerfile, build an image and run it as a container.",["Consistent dev environments","Packaging services"]],"kubernetes":["Open-source system for running and scaling containers.","Automates deployment, scaling and recovery of containerised apps.","Define deployments and services in YAML and apply them to a cluster.",["Microservice platforms","Autoscaling workloads"]],"openshift":["Red Hat's enterprise Kubernetes platform.","Adds security, developer tools and support on top of Kubernetes.","Install or use a managed service, deploy via the console or CLI.",["Enterprise Kubernetes","Hybrid cloud platforms"]],"helm":["Package manager for Kubernetes.","Bundles Kubernetes manifests into reusable, configurable charts.","Install a chart with helm install and override values as needed.",["Deploying standard apps","Versioned releases"]],"podman":["Daemonless container engine compatible with Docker commands.","Runs containers without a root daemon, improving security.","Use podman run and build with the same patterns as Docker.",["Rootless containers","Docker alternative"]],"rancher":["Platform for managing multiple Kubernetes clusters.","One console for clusters across clouds and on-premises.","Install Rancher, import or create clusters and manage access centrally.",["Multi-cluster management","Edge clusters"]],"istio":["Service mesh for Kubernetes.","Adds traffic control, security and observability between services.","Install Istio, inject sidecars and define routing and policies.",["Mutual TLS between services","Canary releases"]],"containerd":["Industry-standard container runtime.","Core runtime used by Kubernetes and Docker.","Configure it as the Kubernetes runtime and manage images with its tools.",["Kubernetes node runtime","Container image handling"]],"amazon eks":["AWS's managed Kubernetes service.","Runs the Kubernetes control plane for you.","Create a cluster, add node groups and deploy workloads with kubectl.",["Kubernetes on AWS","Scalable microservices"]],"azure aks":["Azure's managed Kubernetes service.","Simplifies running Kubernetes with Azure integration.","Create a cluster in Azure, connect with credentials and deploy.",["Kubernetes on Azure","Enterprise container platforms"]],"terraform":["Infrastructure as code tool for provisioning cloud resources.","Reproducible, reviewable infrastructure across many providers.","Write configuration files, run plan and apply and store state safely.",["Provisioning cloud environments","Multi-cloud infrastructure"]],"opentofu":["Open-source fork of Terraform.","Community-governed alternative that is largely compatible.","Use the tofu command with existing Terraform configuration.",["Open-source IaC","Terraform migration"]],"pulumi":["Infrastructure as code using general-purpose programming languages.","Use familiar languages, loops and tests to define infrastructure.","Write infrastructure in TypeScript or Python and run pulumi up.",["Programmable infrastructure","Platform tooling"]],"ansible":["Agentless automation tool for configuration and deployment.","Simple YAML playbooks to configure servers consistently.","Write an inventory and playbooks and run them over SSH.",["Server configuration","Application deployment"]],"cloudformation":["AWS's native infrastructure as code service.","Deeply integrated with AWS and managed by AWS.","Write templates in YAML, create stacks and update them with change sets.",["AWS provisioning","Standardised stacks"]],"bicep":["Azure's domain-specific language for infrastructure as code.","Cleaner and simpler than raw ARM templates.","Write Bicep files and deploy them with the Azure CLI.",["Azure deployments","Azure landing zones"]],"chef":["Configuration management tool using code recipes.","Enforces desired server state at scale.","Write recipes and cookbooks and apply them with Chef Infra.",["Server configuration","Compliance automation"]],"puppet":["Configuration management tool with declarative manifests.","Keeps large fleets of servers consistent.","Write manifests, use a Puppet server and agents to apply them.",["Fleet management","Drift correction"]],"crossplane":["Kubernetes-based framework for managing cloud resources.","Lets platform teams offer self-service infrastructure APIs.","Install on Kubernetes, add providers and define compositions.",["Internal platforms","Cloud resources as Kubernetes objects"]],"packer":["Tool for building machine images.","Creates consistent images across platforms from one template.","Write a template, run packer build and use the images in deployments.",["Golden images","Immutable servers"]],"aws lambda":["AWS's serverless function service.","Runs code on demand without servers and charges only for use.","Write a function, set a trigger and deploy.",["Event-driven functions","APIs behind API Gateway"]],"azure functions":["Azure's serverless compute service.","Event-driven code with many triggers and bindings.","Create a function app, pick a trigger and deploy code.",["Event processing","Scheduled jobs"]],"cloud functions":["Google Cloud's serverless functions service.","Run small pieces of code in response to events.","Write a function, choose a trigger and deploy with gcloud.",["Event handlers","Lightweight APIs"]],"cloud run":["Google Cloud service for running containers serverlessly.","Deploys any container with automatic scaling, including to zero.","Build a container image and deploy it to Cloud Run.",["Containerised APIs","Web services"]],"backstage":["Open-source developer portal framework.","Gives developers one place for services, docs and templates.","Install Backstage, register services in the catalog and add plugins.",["Service catalog","Self-service templates"]],"cloud foundry":["Open-source platform as a service.","Developers push code and the platform handles the rest.","Use the cf CLI to push an app to a configured platform.",["Enterprise PaaS","Simplified deployment"]],"heroku":["Platform as a service for deploying apps easily.","Quick deployment without managing servers.","Connect a Git repository, set a Procfile and push to deploy.",["Prototypes and MVPs","Small production apps"]],"netlify":["Platform for hosting modern web sites and front ends.","Git-based deploys, CDN and serverless functions out of the box.","Connect a repository, set the build command and deploy.",["Static sites","Jamstack apps"]],"fly.io":["Platform for running apps close to users worldwide.","Deploys containers to many regions with simple tooling.","Use flyctl to launch an app and scale across regions.",["Global apps","Low-latency services"]],"vercel":["Platform for deploying front-end and full-stack web apps.","Seamless Next.js deployment with previews and edge functions.","Import a repository and let Vercel build and deploy on each push.",["Next.js hosting","Preview deployments"]],"nginx":["High-performance web server and reverse proxy.","Efficient at serving content and load balancing.","Install it, edit configuration files for sites and upstreams and reload.",["Reverse proxy","Static content serving"]],"apache http":["Long-established open-source web server.","Highly configurable with a large module ecosystem.","Enable modules and configure virtual hosts.",["Hosting websites","Legacy PHP apps"]],"haproxy":["Fast load balancer and proxy.","Reliable high-availability traffic distribution.","Define frontends and backends in a config file and reload.",["Load balancing","TCP and HTTP proxying"]],"f5":["Application delivery and security vendor, known for BIG-IP.","Enterprise load balancing and security.","Configure virtual servers, pools and policies on the appliance or software.",["Enterprise load balancing","Application security"]],"cisco":["Leading networking equipment and software vendor.","Core networking switches, routers and security for enterprises.","Configure devices through CLI or management software and follow design guides.",["Campus and data centre networks","Network security"]],"juniper":["Networking vendor for routers, switches and security.","High-performance carrier and data centre networks.","Configure devices with Junos and manage with automation tools.",["Service provider networks","Data centre fabrics"]],"fortinet":["Cybersecurity vendor known for FortiGate firewalls.","Integrated security with high performance.","Deploy firewalls, define policies and manage with FortiManager.",["Network firewalls","Secure branch connectivity"]],"wireshark":["Network protocol analyser.","Shows exactly what travels over the network for troubleshooting.","Capture traffic on an interface and apply display filters.",["Network troubleshooting","Protocol analysis"]],"envoy":["High-performance edge and service proxy.","Powers many service meshes and API gateways.","Configure listeners and clusters, often through a control plane.",["Service mesh data plane","API gateway"]],"traefik":["Cloud-native reverse proxy and load balancer.","Automatically discovers services and manages certificates.","Run it with Docker or Kubernetes providers and set routing labels.",["Container routing","Automatic HTTPS"]],"linux":["Open-source operating system kernel and family of systems.","Runs most servers, clouds and containers.","Learn the shell, file system, permissions and package management.",["Server hosting","Container hosts"]],"ubuntu":["Popular Linux distribution.","Easy to use with wide community and cloud support.","Install a server image and manage packages with apt.",["Cloud servers","Developer workstations"]],"red hat":["Enterprise Linux distribution with commercial support.","Supported, certified and widely used in enterprises.","Subscribe, install RHEL and manage with its tools.",["Enterprise servers","Certified workloads"]],"windows server":["Microsoft's server operating system.","Runs Active Directory, .NET apps and many enterprise services.","Install it, add roles and features and manage through tools like PowerShell.",["Active Directory","Enterprise applications"]],"vmware":["Virtualisation platform for data centres.","Mature virtual machine management and enterprise features.","Install ESXi, manage with vCenter and create virtual machines.",["Private cloud","Server consolidation"]],"hyper-v":["Microsoft's built-in hypervisor.","Included with Windows and integrated with Microsoft management.","Enable the role, create virtual machines and virtual switches.",["Windows virtualisation","Lab environments"]],"nutanix":["Hyperconverged infrastructure platform.","Simplifies compute and storage in one scalable system.","Deploy nodes, manage through Prism and create virtual machines.",["Private cloud","Simplified data centres"]],"proxmox":["Open-source virtualisation management platform.","Combines KVM and containers with a web interface at low cost.","Install Proxmox, create virtual machines and containers in the UI.",["Home labs","Small business virtualisation"]],"kvm":["Linux kernel-based virtualisation.","Built into Linux, powering many clouds.","Enable KVM, manage VMs with libvirt tools.",["Linux virtualisation","Cloud hypervisors"]],"virtualbox":["Free desktop virtualisation software.","Easy way to run virtual machines locally.","Install it, create a VM and attach an ISO image.",["Test environments","Learning operating systems"]],"git":["Distributed version control system.","Tracks every change and lets teams collaborate safely.","Initialise a repository, commit, branch and merge, and push to a remote.",["Source control","Team collaboration"]],"github":["Platform for hosting Git repositories and collaborating.","Pull requests, issues and Actions in one place with a huge community.","Create a repository, push code and open pull requests for review.",["Code review","Open-source projects"]],"gitlab":["DevOps platform with Git hosting, CI/CD and security.","One integrated product for the whole delivery lifecycle.","Create a project, add a pipeline file and use merge requests.",["Integrated DevOps","Self-hosted source control"]],"bitbucket":["Git hosting from Atlassian.","Integrates tightly with Jira and Atlassian tools.","Create a repository, connect to Jira and set up Pipelines.",["Atlassian-centric teams","Private repositories"]],"jenkins":["Open-source automation server for CI/CD.","Highly extensible with thousands of plugins.","Install it, create pipelines with a Jenkinsfile and connect to source control.",["Build automation","Legacy pipelines"]],"github actions":["CI/CD and automation built into GitHub.","Workflows live next to code and run on events.","Add a workflow YAML file in the repository to build, test and deploy.",["Continuous integration","Automated releases"]],"circleci":["Cloud CI/CD service.","Fast pipelines with caching and parallelism.","Add a config file, connect your repository and run workflows.",["Fast builds","Parallel test runs"]],"azure devops":["Microsoft's suite for boards, repos and pipelines.","Full lifecycle tooling that fits Microsoft environments.","Create a project, set up repos and pipelines and track work on boards.",["Enterprise delivery","Microsoft-stack CI/CD"]],"argo cd":["GitOps continuous delivery tool for Kubernetes.","Keeps clusters in sync with what is declared in Git.","Install it, point an application at a Git repo and let it sync.",["GitOps deployments","Drift detection"]],"flux":["GitOps toolkit for Kubernetes.","Continuously reconciles clusters to Git state.","Bootstrap Flux into a cluster and define sources and kustomizations.",["GitOps automation","Multi-cluster delivery"]],"jfrog":["Platform for managing artifacts and software supply chain.","Single place to store, scan and distribute binaries.","Set up Artifactory repositories and connect build tools.",["Artifact storage","Release management"]],"nexus":["Repository manager for build artifacts and dependencies.","Caches and hosts packages for faster, controlled builds.","Install Nexus, create repositories and point build tools at it.",["Dependency proxying","Private package hosting"]],"harbor":["Open-source container registry with security features.","Adds scanning, signing and access control for images.","Deploy Harbor, create projects and push images.",["Private registry","Image scanning"]],"docker hub":["Public registry for container images.","Easy source of base images and a place to share your own.","Pull official images and push your own with docker push.",["Base images","Sharing containers"]],"artifact registry":["Google Cloud's registry for containers and packages.","Managed storage for images and language packages.","Create a repository, authenticate and push artifacts.",["Container storage on GCP","Package hosting"]],"amazon ecr":["AWS's managed container registry.","Secure image storage that integrates with ECS and EKS.","Create a repository, log in and push images.",["Container images on AWS","Image scanning"]],"sigstore":["Open-source project for signing and verifying software.","Helps prove artifacts are authentic and untampered.","Use cosign to sign images and verify them before deployment.",["Signed releases","Supply chain trust"]],"syft":["Tool that generates software bills of materials.","Shows exactly which components are in your software.","Run Syft on an image or directory to produce an SBOM.",["SBOM generation","Vulnerability tracking"]],"renovate":["Automated dependency update tool.","Keeps libraries current with automatic pull requests.","Enable the app on a repository and configure update rules.",["Dependency updates","Security patches"]],"dependabot":["GitHub's automated dependency update service.","Alerts and fixes vulnerable dependencies.","Enable it in repository settings and review the pull requests.",["Vulnerable dependency fixes","Routine updates"]],"selenium":["Browser automation framework for web testing.","Long-standing standard supporting many languages and browsers.","Write tests with WebDriver and run them locally or on a grid.",["Cross-browser tests","Regression suites"]],"cypress":["JavaScript end-to-end testing framework.","Fast feedback and easy debugging for web apps.","Install it, write specs and run in the interactive runner.",["Front-end end-to-end tests","Component tests"]],"playwright":["Modern browser automation and testing tool from Microsoft.","Reliable tests across Chromium, Firefox and WebKit.","Install it, write tests and run them in parallel.",["Cross-browser testing","Auto-waiting UI tests"]],"postman":["Platform for building and testing APIs.","Makes exploring and testing APIs easy and shareable.","Create requests, organise collections and add tests.",["API testing","API documentation"]],"junit":["Unit testing framework for Java.","Standard for fast, repeatable Java tests.","Write test methods with annotations and run them via your build tool.",["Unit testing","Test-driven development"]],"testng":["Testing framework for Java with flexible configuration.","Supports grouping, parameters and parallel runs.","Annotate tests and define suites in XML.",["Integration test suites","Parallel tests"]],"pytest":["Python testing framework.","Simple tests with powerful fixtures.","Write test functions with assert statements and run pytest.",["Python unit tests","Fixtures and parametrised tests"]],"jmeter":["Open-source load testing tool.","Measures performance under heavy traffic.","Build a test plan, add samplers and run in non-GUI mode.",["Load testing","Performance baselines"]],"k6":["Developer-friendly load testing tool.","Scripts in JavaScript and fits CI pipelines.","Write a test script, run it with k6 and set thresholds.",["Performance tests in CI","API load testing"]],"appium":["Automation framework for mobile app testing.","One API for iOS and Android UI tests.","Start the Appium server and write tests with WebDriver clients.",["Mobile UI testing","Device farm tests"]],"okta":["Identity and access management platform.","Central sign-in and single sign-on for apps.","Connect apps via SAML or OIDC and set policies.",["Single sign-on","Multi-factor authentication"]],"hashicorp vault":["Secrets management and encryption tool.","Keeps credentials out of code and rotates them.","Run Vault, enable a secrets engine and let apps fetch secrets via API.",["Secrets storage","Dynamic credentials"]],"sonarqube":["Code quality and security analysis platform.","Finds bugs, smells and vulnerabilities early.","Run the scanner in CI and review the quality gate.",["Static analysis","Quality gates"]],"snyk":["Developer-first security platform.","Finds vulnerabilities in code, dependencies and containers.","Connect repositories or CLI, scan and apply suggested fixes.",["Dependency scanning","Container security"]],"crowdstrike":["Endpoint protection and threat detection platform.","Cloud-based detection and response for endpoints.","Deploy the Falcon agent and monitor detections in the console.",["Endpoint security","Threat hunting"]],"palo alto networks":["Cybersecurity vendor for firewalls and cloud security.","Broad security platform for network and cloud.","Deploy firewalls or Prisma Cloud and configure policies.",["Next-generation firewalls","Cloud security"]],"wiz":["Cloud security platform.","Gives agentless visibility into risks across cloud accounts.","Connect cloud accounts and review prioritised risks.",["Cloud posture management","Vulnerability prioritisation"]],"trivy":["Open-source vulnerability and misconfiguration scanner.","Quick scans of images, code and infrastructure files.","Run trivy against an image, filesystem or repository.",["Container scanning","IaC checks"]],"burp suite":["Web application security testing toolkit.","Standard for manual and automated web testing.","Proxy browser traffic through Burp and probe requests.",["Penetration testing","Web vulnerability scanning"]],"keycloak":["Open-source identity and access management.","Provides login, SSO and user management without licence cost.","Run Keycloak, create a realm and client and integrate via OIDC.",["Application sign-in","Self-hosted identity"]],"prometheus":["Open-source monitoring system with a time-series database.","Standard for metrics in cloud-native environments.","Expose metrics endpoints, configure scraping and write alert rules.",["Metrics collection","Alerting"]],"grafana":["Open-source dashboard and visualisation platform.","Brings metrics, logs and traces into shared dashboards.","Add data sources, build dashboards and set alerts.",["Operations dashboards","Unified observability"]],"datadog":["Cloud monitoring and security platform.","Unified metrics, logs and traces with easy setup.","Install the agent, enable integrations and build dashboards.",["Full-stack monitoring","Incident detection"]],"new relic":["Observability platform for applications and infrastructure.","Deep application performance insight.","Install an agent in your app and explore traces and metrics.",["Application performance monitoring","Error tracking"]],"splunk":["Platform for searching and analysing machine data.","Powerful log search and security analytics.","Forward logs to Splunk, search with SPL and create dashboards.",["Log analysis","Security operations"]],"elk stack":["Elasticsearch, Logstash and Kibana for log analytics.","Flexible, open way to collect, search and visualise logs.","Ship logs with Beats or Logstash, index in Elasticsearch and view in Kibana.",["Centralised logging","Log search"]],"opentelemetry":["Open standard for collecting traces, metrics and logs.","Vendor-neutral instrumentation for observability.","Add SDKs to your app and send data to a collector and backend.",["Distributed tracing","Standard instrumentation"]],"dynatrace":["Observability platform with automatic discovery and AI.","Auto-detects dependencies and finds root causes quickly.","Install OneAgent and review auto-discovered topology.",["Enterprise APM","Root-cause analysis"]],"jaeger":["Open-source distributed tracing system.","Shows how a request flows through microservices.","Instrument services, send traces and search them in the UI.",["Tracing microservices","Latency analysis"]],"pagerduty":["Incident response and on-call management platform.","Gets the right person alerted quickly.","Connect monitoring tools, set escalation policies and on-call schedules.",["On-call alerts","Incident coordination"]],"agile":["Mindset and set of practices for iterative, collaborative delivery.","Responds to change and delivers value early.","Work in short iterations, gather feedback and adapt plans.",["Product development","Changing requirements"]],"scrum":["Agile framework with sprints, roles and ceremonies.","Provides rhythm and clarity for team delivery.","Plan a sprint, hold daily stand-ups, review and run a retrospective.",["Software teams","Sprint-based delivery"]],"kanban":["Visual method for managing flow of work.","Limits work in progress and exposes bottlenecks.","Create a board with columns, set limits and pull work through.",["Support teams","Continuous flow"]],"safe":["Framework for scaling agile across large organisations.","Aligns many teams around shared planning.","Organise teams into release trains and plan in program increments.",["Large enterprises","Coordinated releases"]],"devops":["Culture and practices joining development and operations.","Speeds up delivery while improving reliability.","Automate build, test and deploy and share ownership of running systems.",["Faster releases","Shared accountability"]],"sre":["Site reliability engineering applies software engineering to operations.","Balances reliability with speed using clear targets.","Define service level objectives, error budgets and automate toil.",["Reliability programs","On-call improvement"]],"itil 4":["Framework of best practices for IT service management.","Common language and processes for delivering services.","Adopt practices such as incident, change and service request management.",["Service desks","Change control"]],"finops":["Practice of managing cloud costs collaboratively.","Makes cloud spend visible and accountable.","Tag resources, report costs by team and optimise usage.",["Cost optimisation","Cloud budgeting"]],"gitops":["Operating model using Git as the source of truth for infrastructure.","Brings review and audit to deployments.","Store desired state in Git and let a controller apply it.",["Kubernetes delivery","Auditable changes"]],"tdd/bdd":["Test-driven and behaviour-driven development.","Improves design and ensures shared understanding of behaviour.","Write failing tests first, then code, and describe behaviour in plain language.",["Quality-focused teams","Shared acceptance criteria"]],"iot":["Internet of Things connects physical devices to networks.","Provides real-time data from machines and environments.","Connect sensors to gateways and cloud platforms and process the data.",["Smart factories","Asset tracking"]],"edge computing":["Processing data close to where it is produced.","Reduces latency and bandwidth use.","Deploy small compute nodes near devices and sync with the cloud.",["Real-time analytics","Remote sites"]],"ar/vr":["Augmented and virtual reality create immersive experiences.","Enables training, design and visualisation in new ways.","Build experiences with engines such as Unity for headsets or phones.",["Training simulations","Product visualisation"]],"blockchain":["Distributed ledger with tamper-resistant records.","Shared trust without a central authority.","Choose a platform, design smart contracts and integrate with systems.",["Supply chain tracking","Digital assets"]],"quantum computing":["Computing using quantum mechanics for certain problems.","Could solve some problems far faster than classical computers.","Experiment with cloud quantum services and simulators.",["Optimisation research","Cryptography research"]],"robotics":["Machines that sense and act in the physical world.","Automates physical tasks with precision.","Combine sensors, control software and AI, often with ROS.",["Warehouse automation","Manufacturing"]],"5g":["Fifth-generation mobile network technology.","Higher speeds, low latency and many connected devices.","Use 5G connectivity for devices and design apps for variable networks.",["Connected devices","Low-latency apps"]],"digital twins":["Virtual replicas of physical assets or systems.","Simulate and monitor real assets to optimise them.","Feed sensor data into a model and run simulations.",["Predictive maintenance","Factory simulation"]],"web3":["Decentralised web concepts built on blockchain.","Explores user-owned data and applications.","Use wallets and smart contracts for decentralised applications.",["Decentralised apps","Digital ownership"]],"green it":["Practice of reducing the environmental impact of technology.","Cuts energy use and costs while meeting sustainability goals.","Measure energy use, right-size systems and choose efficient regions.",["Sustainable cloud","Efficient data centres"]]},"routes":[{"id":"web","kind":"journey","name":"Launch a modern web application","short":"Launch a web app","brief":"From design to a monitored production site.","tools":["Figma","TypeScript","React","Node.js","PostgreSQL","Playwright","Docker","GitHub Actions","AWS","Grafana"],"notes":["Design the screens and flows","Write typed, safer code","Build the interface from components","Serve the API","Store the data","Test the real user flows","Package the app","Build, test and deploy on every push","Run it in the cloud","Watch it live"],"story":"You have an idea for a website or web app and want real users on it. This is the path from sketch to a monitored live product.","outcome":"A live web app that deploys automatically and that you can watch in real time.","phases":[{"t":"Design the experience","d":"Before any code, sketch the screens and how a person moves between them. Share the clickable design with stakeholders and fix confusion while it is still cheap.","out":"Approved screen designs and a clickable prototype.","risk":"Skipping this and designing in code leads to rework.","tools":["Figma"]},{"t":"Build the product","d":"Developers build what people see (React), the server that answers requests (Node.js) and the database that remembers things (PostgreSQL). TypeScript keeps the code safer as it grows.","out":"A working app running on a developer machine.","risk":"Growing features before the data model is settled.","tools":["TypeScript","React","Node.js","PostgreSQL"]},{"t":"Prove it works","d":"Automated browser tests click through the important journeys such as sign-up and checkout, so every change is checked the same way.","out":"A test suite that passes on every change.","risk":"Testing only happy paths.","tools":["Playwright"]},{"t":"Package and automate","d":"Docker wraps the app so it runs the same everywhere. GitHub Actions builds, tests and deploys it automatically whenever code changes.","out":"One-click or automatic deployments.","risk":"Manual release steps that only one person knows.","tools":["Docker","GitHub Actions"]},{"t":"Launch and watch","d":"The app goes live on the cloud. Dashboards show traffic, errors and speed so you notice problems before users complain.","out":"A live site with health dashboards.","risk":"Launching without any monitoring.","tools":["AWS","Grafana"]}]},{"id":"cloud","kind":"journey","name":"Modernize and operate a cloud service","short":"Run a cloud service","brief":"Plan, provision, ship and operate a service on the cloud.","tools":["Jira","C4 Model","Terraform","Microsoft Azure","Docker","Kubernetes","GitHub Actions","Prometheus","Grafana","ServiceNow","ITIL 4"],"notes":["Plan and track the work","Draw the architecture","Provision the environment as code","Host the platform","Containerise the service","Orchestrate and scale it","Automate delivery","Collect metrics","Visualise health","Handle incidents and changes","Run it with service practices"],"story":"A service exists, or must be moved to the cloud, and the business expects it to be reliable and supportable.","outcome":"A service running on managed infrastructure with automated delivery, monitoring and a support process.","phases":[{"t":"Plan and design","d":"Capture the work as a backlog and draw the architecture at several zoom levels so everyone shares one picture of the system.","out":"A prioritised backlog and architecture diagrams.","risk":"Diagrams that nobody keeps up to date.","tools":["Jira","C4 Model"]},{"t":"Prepare the platform","d":"Describe networks, servers and services as code, then create them on Azure. The environment can be rebuilt on demand.","out":"A repeatable cloud environment.","risk":"Clicking things together by hand in the portal.","tools":["Terraform","Microsoft Azure"]},{"t":"Package and run","d":"The service is containerised and Kubernetes keeps the right number of copies running, restarting any that fail.","out":"The service running in containers at scale.","risk":"Running too many tiny services too early.","tools":["Docker","Kubernetes"]},{"t":"Automate delivery","d":"Each change is built, tested and rolled out by a pipeline, giving small, frequent and safe releases.","out":"A pipeline from commit to production.","risk":"Pipelines with no automated tests.","tools":["GitHub Actions"]},{"t":"Observe","d":"Collect numbers about health and speed, then show them on dashboards with alerts for unusual behaviour.","out":"Dashboards and alerts for the service.","risk":"Alerts so noisy that people ignore them.","tools":["Prometheus","Grafana"]},{"t":"Support and govern","d":"Incidents, requests and changes flow through a ticketing system following agreed service practices, so support is consistent.","out":"A working support process.","risk":"Process with no link to real operations.","tools":["ServiceNow","ITIL 4"]}]},{"id":"ai","kind":"journey","name":"Deliver an enterprise AI assistant","short":"Ship an AI assistant","brief":"A retrieval-based assistant that answers from company knowledge.","tools":["Python","FastAPI","OpenAI","LangChain","Qdrant","Docker","AWS","OpenTelemetry","Snyk"],"notes":["Glue everything together","Expose the assistant as an API","Generate answers with a model","Orchestrate prompts and retrieval","Store and search embeddings","Package the service","Deploy it","Trace each request","Scan for vulnerabilities"],"story":"The business wants an assistant that answers questions from its own documents, safely.","outcome":"A deployed AI assistant service that answers from company knowledge and can be traced and secured.","phases":[{"t":"Set up the service","d":"Start with a small web service that accepts a question and returns an answer. Python is the glue for most AI work.","out":"A simple API endpoint.","risk":"Starting with a complex framework before the basics work.","tools":["Python","FastAPI"]},{"t":"Add intelligence","d":"Company documents are turned into searchable vectors in Qdrant. For each question the best passages are found and handed to a language model, with LangChain coordinating the steps.","out":"An assistant that answers from your documents.","risk":"Answers that sound confident but are not grounded in the documents.","tools":["OpenAI","LangChain","Qdrant"]},{"t":"Package and deploy","d":"Wrap the service in a container and run it on the cloud so many people can use it.","out":"A hosted assistant with a stable address.","risk":"Forgetting cost limits on model usage.","tools":["Docker","AWS"]},{"t":"Trust and monitor","d":"Trace each request to see where time and cost go, and scan the code and libraries for security problems.","out":"Traceable requests and a security scan.","risk":"Sending sensitive data to a model without review.","tools":["OpenTelemetry","Snyk"]}]},{"id":"services","kind":"journey","name":"Run an enterprise managed service","short":"Operate managed services","brief":"Keep a business service healthy, supported and affordable.","tools":["ServiceNow","Jira","AWS","Kubernetes","Prometheus","Grafana","PagerDuty","Splunk","ITIL 4","FinOps"],"notes":["Receive requests and incidents","Track engineering work","Host the service","Run the workloads","Measure service health","Share dashboards","Page the on-call engineer","Investigate logs","Follow service management practice","Keep the cost in check"],"story":"A business application is live and people depend on it every day. Your job is to keep it healthy, supported and affordable.","outcome":"A managed service with clear support, monitoring, on-call response and cost control.","phases":[{"t":"Take in work","d":"Users raise requests and incidents in ServiceNow. Engineering work that follows is tracked in Jira.","out":"One front door for issues and requests.","risk":"Requests arriving by email and chat instead.","tools":["ServiceNow","Jira"]},{"t":"Host and run","d":"The service runs on cloud infrastructure with Kubernetes keeping the workloads healthy.","out":"A stable production platform.","risk":"No separation between test and production.","tools":["AWS","Kubernetes"]},{"t":"Monitor health","d":"Measure uptime, speed and errors, and display them for support and business teams.","out":"Shared health dashboards.","risk":"Measuring technical numbers that users do not feel.","tools":["Prometheus","Grafana"]},{"t":"Respond to problems","d":"When something breaks the right engineer is paged and uses logs in Splunk to find the cause.","out":"A defined on-call and investigation routine.","risk":"Heroics instead of a rota.","tools":["PagerDuty","Splunk"]},{"t":"Govern and optimise","d":"Service practices keep changes controlled, and cost reviews keep the cloud bill in line with value.","out":"Regular service and cost reviews.","risk":"Reviews with no action.","tools":["ITIL 4","FinOps"]}]},{"id":"mobile","kind":"journey","name":"Ship a mobile app","short":"Ship a mobile app","brief":"Design, build, test and monitor a cross-platform app.","tools":["Figma","Flutter","Node.js","PostgreSQL","Appium","GitHub Actions","Google Cloud","Datadog"],"notes":["Design the app screens","Build for iOS and Android","Provide the back end","Store user data","Automate device tests","Build and release automatically","Host the back end","Watch crashes and performance"],"story":"You want a mobile app on the App Store and Google Play, with a back end behind it.","outcome":"An app available on both platforms, with automated releases and live monitoring.","phases":[{"t":"Design the app","d":"Design each screen for small devices, thumbs and poor connections, then test the prototype with real users.","out":"Screen designs and a tested prototype.","risk":"Designing for desktop habits.","tools":["Figma"]},{"t":"Build app and back end","d":"One Flutter codebase produces the iOS and Android apps. Node.js provides the services and PostgreSQL stores the data.","out":"A working app talking to a working back end.","risk":"Ignoring offline and slow networks.","tools":["Flutter","Node.js","PostgreSQL"]},{"t":"Test on devices","d":"Automated tests drive the real app on many phones and screen sizes to catch layout and behaviour problems.","out":"A device test suite.","risk":"Testing on one phone only.","tools":["Appium"]},{"t":"Release","d":"A pipeline builds the app, runs tests and ships it to the stores, while the back end is hosted on the cloud.","out":"Repeatable store releases and a hosted back end.","risk":"Store review delays not planned for.","tools":["GitHub Actions","Google Cloud"]},{"t":"Operate and improve","d":"Watch crashes, slow screens and server health, and use that evidence to decide what to fix next.","out":"Crash and performance dashboards.","risk":"Not tracking app versions in the field.","tools":["Datadog"]}]},{"id":"stream","kind":"journey","name":"Build a real-time data platform","short":"Real-time data platform","brief":"Turn live events into trusted dashboards.","tools":["Kafka","Flink","Airflow","dbt","Snowflake","Power BI","Grafana"],"notes":["Capture events as they happen","Process the stream","Orchestrate batch jobs","Transform data with SQL","Store it for analysis","Share dashboards","Monitor the pipeline"],"story":"Events such as orders, clicks or sensor readings arrive constantly, and decision makers want live, trusted numbers.","outcome":"A pipeline from live events to dashboards that people trust.","phases":[{"t":"Capture events","d":"Applications publish events to Kafka, which stores them durably so that many consumers can read them.","out":"A reliable stream of business events.","risk":"Unclear ownership of event formats.","tools":["Kafka"]},{"t":"Process the stream","d":"Flink cleans, joins and counts events as they arrive, for example spotting a spike in failed payments.","out":"Real-time computed results.","risk":"Late or duplicate events skewing totals.","tools":["Flink"]},{"t":"Organise and store","d":"Airflow schedules the batch work, dbt turns raw tables into clean business tables, and Snowflake stores them for analysis.","out":"Modelled, documented warehouse tables.","risk":"No tests on data quality.","tools":["Airflow","dbt","Snowflake"]},{"t":"Deliver insight","d":"Dashboards put the clean data in front of managers and analysts in terms they understand.","out":"Self-service dashboards.","risk":"Several versions of the same metric.","tools":["Power BI"]},{"t":"Keep it healthy","d":"Monitor delays, volumes and failures in the pipeline itself so data problems are found by you first.","out":"Pipeline health dashboards.","risk":"Silent failures that nobody notices.","tools":["Grafana"]}]},{"id":"secure","kind":"journey","name":"Secure the delivery pipeline","short":"Secure the pipeline","brief":"Add security checks at every step from commit to cluster.","tools":["Git","GitHub","SonarQube","Snyk","Trivy","Sigstore","HashiCorp Vault","Argo CD","Wiz"],"notes":["Version every change","Review changes in pull requests","Check code quality","Find vulnerable dependencies","Scan container images","Sign what you ship","Keep secrets out of code","Deploy only what Git declares","Watch cloud risk"],"story":"Code ships quickly, and security must keep pace without slowing teams down.","outcome":"A delivery pipeline with checks at every stage and secrets kept out of code.","phases":[{"t":"Commit with control","d":"Every change is recorded and reviewed in a pull request before it merges, creating an audit trail.","out":"Reviewed, traceable changes.","risk":"Direct pushes to the main branch.","tools":["Git","GitHub"]},{"t":"Check the code","d":"SonarQube looks for bugs and weak patterns in your code, and Snyk flags vulnerable libraries you depend on.","out":"Automatic code and dependency checks.","risk":"Reports nobody is required to act on.","tools":["SonarQube","Snyk"]},{"t":"Check what you ship","d":"Trivy scans container images for known flaws, and Sigstore signs the approved build so tampering is detectable.","out":"Scanned and signed images.","risk":"Scanning once, not on every build.","tools":["Trivy","Sigstore"]},{"t":"Protect secrets and deploy","d":"Passwords and keys live in Vault, not in code. Argo CD deploys only what Git says should run.","out":"No secrets in repos and Git-driven deployments.","risk":"Long-lived shared credentials.","tools":["HashiCorp Vault","Argo CD"]},{"t":"Watch cloud risk","d":"Continuously look for exposed services and risky settings across cloud accounts and rank what to fix first.","out":"A prioritised cloud risk list.","risk":"Findings with no owner.","tools":["Wiz"]}]},{"id":"legacy","kind":"journey","name":"Modernize a legacy system","short":"Modernize legacy","brief":"Move an old monolith to containers on managed Kubernetes.","tools":["C4 Model","Spring Boot","Docker","Terraform","Amazon EKS","OpenTelemetry","FinOps"],"notes":["Map what exists today","Rebuild services step by step","Containerise them","Provision the target platform","Run on managed Kubernetes","Trace across the new services","Track cloud spend"],"story":"An important system works but is hard to change. You want it modern without a risky big-bang rewrite.","outcome":"Services running in containers on managed Kubernetes, with visibility and cost control.","phases":[{"t":"Understand today","d":"Draw what exists: who uses it, what it talks to, and which parts are tangled. This map decides what to move first.","out":"Current-state architecture diagrams.","risk":"Assuming the old documentation is right.","tools":["C4 Model"]},{"t":"Rebuild in pieces","d":"Carve out one capability at a time into a Spring Boot service packaged in a container, while the old system keeps running.","out":"First service live beside the legacy system.","risk":"Moving too much at once.","tools":["Spring Boot","Docker"]},{"t":"Prepare the new platform","d":"Create the target platform as code and run the new services on managed Kubernetes.","out":"A repeatable production platform.","risk":"Building the platform before knowing the needs.","tools":["Terraform","Amazon EKS"]},{"t":"Operate and optimise","d":"Trace requests across old and new parts, and track spend so modernisation does not become a surprise bill.","out":"Visibility and a cost baseline.","risk":"Running two systems longer than planned.","tools":["OpenTelemetry","FinOps"]}]},{"id":"t-fullstack","kind":"track","name":"Full-stack developer","short":"Full-stack developer","brief":"Build whole web products, from page to database.","tools":["HTML5","CSS3","JavaScript","TypeScript","React","Node.js","REST","PostgreSQL","Git","Docker","Playwright"],"notes":["Structure of every page","Layout and style","The language of the browser","Add types","Component-based UI","Server-side JavaScript","Design clean APIs","Relational data","Collaborate on code","Package and run anywhere","Test end to end"],"story":"You want to build complete web products on your own, from page to database.","outcome":"You can design, build, test and ship a full web application.","phases":[{"t":"Web foundations","d":"Learn how a page is structured, styled and made interactive. Build a few static pages and one small interactive page.","out":"A portfolio of small pages.","risk":"Jumping to frameworks before the basics.","tools":["HTML5","CSS3","JavaScript"]},{"t":"Level up the front end","d":"Add types for safety and React for building interfaces from reusable pieces. Rebuild a page as components.","out":"A multi-screen React app.","risk":"Copying tutorials without understanding state.","tools":["TypeScript","React"]},{"t":"Back end and data","d":"Build the server, design clean API endpoints and store data in a real database. Connect it to your front end.","out":"A full-stack app with sign-in and saved data.","risk":"Ignoring database design.","tools":["Node.js","REST","PostgreSQL"]},{"t":"Professional habits","d":"Track your work with Git, package the app with Docker and protect it with automated browser tests.","out":"A tested, containerised project in a repository.","risk":"Leaving testing until the end.","tools":["Git","Docker","Playwright"]}]},{"id":"t-cloud","kind":"track","name":"Cloud engineer","short":"Cloud engineer","brief":"Build and run reliable cloud platforms.","tools":["Linux","Git","Docker","Kubernetes","Terraform","AWS","Prometheus","Grafana","FinOps"],"notes":["Know the operating system","Version your work","Containers first","Orchestrate containers","Infrastructure as code","Learn one cloud deeply","Observe your systems","Dashboards","Control cost"],"story":"You want to build and run reliable platforms on the cloud.","outcome":"You can provision, run and monitor cloud workloads.","phases":[{"t":"Foundations","d":"Get comfortable in the Linux shell and use Git for everything. Almost every cloud tool assumes both.","out":"Daily comfort in a terminal.","risk":"Avoiding the command line.","tools":["Linux","Git"]},{"t":"Containers","d":"Package an application in a container, then run and scale it with Kubernetes on a small cluster.","out":"An app running on Kubernetes.","risk":"Learning Kubernetes before Docker.","tools":["Docker","Kubernetes"]},{"t":"Cloud and code","d":"Learn one cloud properly, then create its resources through Terraform instead of clicking.","out":"An environment built from code.","risk":"Spreading across several clouds too soon.","tools":["Terraform","AWS"]},{"t":"Operate","d":"Add monitoring and dashboards, and learn to keep an eye on cost.","out":"Monitoring and a cost view for your project.","risk":"Forgetting to switch resources off.","tools":["Prometheus","Grafana","FinOps"]}]},{"id":"t-data","kind":"track","name":"Data engineer","short":"Data engineer","brief":"Move, shape and serve data at scale.","tools":["Python","PostgreSQL","Kafka","Apache Spark","Airflow","dbt","Snowflake","Power BI"],"notes":["The data lingua franca","Master SQL and modelling","Streaming ingestion","Big data processing","Orchestrate pipelines","Transform in the warehouse","Cloud warehousing","Deliver insight"],"story":"You want to move, shape and serve data so the business can decide with confidence.","outcome":"You can build a pipeline from raw data to a dashboard.","phases":[{"t":"Foundations","d":"Learn Python for handling data and SQL for asking questions of it. These two carry the whole career.","out":"Comfortable SQL and Python scripts.","risk":"Skipping SQL practice.","tools":["Python","PostgreSQL"]},{"t":"Move and process data","d":"Learn streaming with Kafka and large-scale processing with Spark.","out":"A stream and a batch job working with real data.","risk":"Using big tools for small data.","tools":["Kafka","Apache Spark"]},{"t":"Orchestrate and model","d":"Schedule pipelines, transform data into clean models and store it in a cloud warehouse.","out":"A scheduled pipeline into a warehouse.","risk":"Models with no tests.","tools":["Airflow","dbt","Snowflake"]},{"t":"Deliver insight","d":"Turn the warehouse into dashboards people use.","out":"A dashboard answering a real question.","risk":"Building charts nobody asked for.","tools":["Power BI"]}]},{"id":"t-sre","kind":"track","name":"DevOps / SRE","short":"DevOps / SRE","brief":"Automate delivery and keep services reliable.","tools":["Linux","Git","GitHub Actions","Docker","Kubernetes","Prometheus","Grafana","OpenTelemetry","PagerDuty","SRE"],"notes":["Operate servers","Source control","Build CI/CD","Containers","Run at scale","Metrics and alerts","Dashboards","Traces","On-call response","Reliability practice"],"story":"You want to automate delivery and keep services reliable.","outcome":"You can build pipelines, observe systems and respond to incidents.","phases":[{"t":"Foundations","d":"Know the operating system and keep all configuration in version control.","out":"Everything you write lives in Git.","risk":"Making changes directly on servers.","tools":["Linux","Git"]},{"t":"Automate delivery","d":"Build a pipeline that tests, packages and deploys an app onto a cluster.","out":"Commit-to-cluster automation.","risk":"Pipelines without rollback.","tools":["GitHub Actions","Docker","Kubernetes"]},{"t":"Observe","d":"Collect metrics, display them and trace requests across services.","out":"Metrics, dashboards and traces for one app.","risk":"Collecting data without questions in mind.","tools":["Prometheus","Grafana","OpenTelemetry"]},{"t":"Respond and improve","d":"Set reliability targets, run on-call and learn from incidents with blameless reviews.","out":"A reliability target and an incident routine.","risk":"Chasing 100 percent uptime.","tools":["PagerDuty","SRE"]}]},{"id":"t-ai","kind":"track","name":"AI engineer","short":"AI engineer","brief":"Go from models to production AI apps.","tools":["Python","scikit-learn","PyTorch","Hugging Face","LangChain","Qdrant","FastAPI","MLflow","MCP"],"notes":["Core language","Classic machine learning","Deep learning","Pretrained models","Build LLM apps","Vector search","Serve models","Track experiments","Connect tools to models"],"story":"You want to take AI from a notebook to a product people use.","outcome":"You can build, serve and track AI-powered applications.","phases":[{"t":"Foundations","d":"Learn Python and classic machine learning on small tables of data, including how to judge a model fairly.","out":"A simple prediction model with honest evaluation.","risk":"Judging models on the data they trained on.","tools":["Python","scikit-learn"]},{"t":"Deep learning and models","d":"Understand neural networks and learn to reuse pretrained models instead of training from scratch.","out":"A fine-tuned or reused model.","risk":"Training when a pretrained model would do.","tools":["PyTorch","Hugging Face"]},{"t":"Build AI apps","d":"Connect language models to your own documents with a vector store and expose the result as an API.","out":"A question-answering service.","risk":"No way to check answer quality.","tools":["LangChain","Qdrant","FastAPI"]},{"t":"Production and tools","d":"Track experiments and versions, and let models use outside tools in a standard way.","out":"Tracked experiments and a tool-using assistant.","risk":"Models changing silently.","tools":["MLflow","MCP"]}]},{"id":"t-security","kind":"track","name":"Security engineer","short":"Security engineer","brief":"Protect code, pipelines and cloud.","tools":["Linux","Git","SonarQube","Snyk","Trivy","HashiCorp Vault","Keycloak","Wiz","Burp Suite"],"notes":["Systems fundamentals","Secure workflows","Static analysis","Dependency risk","Image scanning","Secrets","Identity and access","Cloud posture","Test web apps"],"story":"You want to protect code, pipelines and cloud environments.","outcome":"You can find and fix weaknesses across the delivery lifecycle.","phases":[{"t":"Foundations","d":"Understand how systems and code changes work before trying to secure them.","out":"Comfort with permissions, processes and repositories.","risk":"Learning tools without fundamentals.","tools":["Linux","Git"]},{"t":"Secure the code","d":"Scan your own code, its libraries and its container images, then practise fixing what is found.","out":"Scans running on a sample project.","risk":"Treating every finding as equal.","tools":["SonarQube","Snyk","Trivy"]},{"t":"Secrets and identity","d":"Keep secrets in a vault and manage who can sign in and what they can do.","out":"A project with managed secrets and sign-in.","risk":"Hard-coded credentials.","tools":["HashiCorp Vault","Keycloak"]},{"t":"Cloud and attack testing","d":"Review cloud risk and learn to test web apps the way an attacker would, with permission.","out":"A short assessment report.","risk":"Testing without written approval.","tools":["Wiz","Burp Suite"]}]},{"id":"t-architect","kind":"track","name":"Solution architect","short":"Solution architect","brief":"Design systems that fit the business and run well.","tools":["Agile","C4 Model","REST","PostgreSQL","Kafka","Kubernetes","Terraform","OpenTelemetry","FinOps"],"notes":["Work with delivery teams","Communicate architecture","Define interfaces","Choose data stores","Event-driven design","Platform choices","Repeatable environments","Design for observability","Design for cost"],"story":"You want to design systems that fit the business and run well.","outcome":"You can frame a solution, choose building blocks and explain trade-offs.","phases":[{"t":"Frame the work","d":"Understand how delivery teams work and learn to communicate a design clearly at the right level of detail.","out":"A system context diagram and a first backlog.","risk":"Designing in isolation from the team.","tools":["Agile","C4 Model"]},{"t":"Design interfaces and data","d":"Decide how systems talk to each other, where data is stored and when to use events instead of requests.","out":"An interface and data design.","risk":"Choosing a tool before the need is clear.","tools":["REST","PostgreSQL","Kafka"]},{"t":"Platform choices","d":"Understand where the solution will run and how its environments are created repeatably.","out":"A deployment and environment approach.","risk":"Over-engineering the platform.","tools":["Kubernetes","Terraform"]},{"t":"Run and cost","d":"Design in visibility and a cost view from day one.","out":"An observability and cost plan.","risk":"Treating run cost as a problem for another team.","tools":["OpenTelemetry","FinOps"]}]}],"mark":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><circle cx=\"32\" cy=\"32.5\" r=\"32.7\" fill=\"#1A1915\"/><path d=\"M51.69 50.23 A26.50 26.50 0 1 1 57.20 24.31\" fill=\"none\" stroke-width=\"5.6\" stroke-linecap=\"round\" stroke=\"#F3F1EA\"/><path d=\"M57.20 24.31 A26.50 26.50 0 0 1 51.69 50.23\" fill=\"none\" stroke-width=\"5.6\" stroke-linecap=\"round\" stroke=\"#F0B43C\"/><path d=\"M24.1 19.5 H26.299999999999997 A2.6 2.6 0 0 1 28.9 22.1 V43.9 A2.6 2.6 0 0 1 26.299999999999997 46.5 H24.1 A2.6 2.6 0 0 1 21.5 43.9 V22.1 A2.6 2.6 0 0 1 24.1 19.5 Z\" fill=\"#FFFFFF\"/><path d=\"M28.75 14.22 A12.40 12.40 0 1 1 28.54 38.97 L29.01 32.19 A5.60 5.60 0 1 0 29.11 21.01 Z\" fill=\"#FFFFFF\"/></svg>"}
